fn relativize(path: &str, root: &std::path::Path) -> String {
    let root_str = root.to_string_lossy();
    let prefix = format!("{}/", root_str.trim_end_matches('/'));
    path.strip_prefix(&prefix).unwrap_or(path).to_string()
}

fn transcript_artifact_root(path: &Path) -> Result<PathBuf> {
    let canonical = path
        .canonicalize()
        .with_context(|| format!("canonicalizing {}", path.display()))?;
    let start = if canonical.is_dir() {
        canonical.clone()
    } else {
        canonical
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| canonical.clone())
    };

    for ancestor in start.ancestors() {
        if ancestor.join(".git").exists() || ancestor.join(".gitmodules").is_file() {
            return Ok(ancestor.to_path_buf());
        }
    }

    Ok(start)
}

fn relativize_pathbuf(path: &std::path::Path, root: &std::path::Path) -> PathBuf {
    path.strip_prefix(root)
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|_| path.to_path_buf())
}

fn relativize_edges(edges: &mut [index::StoredEdge], root: &std::path::Path) {
    for edge in edges {
        edge.caller_file = relativize(&edge.caller_file, root);
    }
}

fn relativize_symbols(symbols: &mut [index::StoredSymbol], root: &std::path::Path) {
    for sym in symbols {
        sym.file = relativize(&sym.file, root);
    }
}

fn relativize_symbol_hits(hits: &mut [index::SymbolHit], root: &std::path::Path) {
    for hit in hits {
        hit.file = relativize(&hit.file, root);
    }
}

/// Diagnostic produced by [`annotate_hits_with_tagpath`].
#[derive(Debug, Default, Clone)]
pub struct TagpathAnnotationDiagnostic {
    pub stale: bool,
    pub reason: Option<String>,
    pub loaded: bool,
    pub ambiguous_members: Vec<CommunityMemberAmbiguityDiagnostic>,
}

#[derive(Debug, Clone, Serialize)]
pub struct CommunityMemberAmbiguityDiagnostic {
    pub community_id: usize,
    pub name: String,
    pub candidate_count: usize,
    pub tagpath_candidate_count: usize,
    pub evidence: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub chosen_file: Option<String>,
}

const COMMUNITY_DETECTION_CACHE_VERSION: &str = "community-detection-cache-v1";

static COMMUNITY_DETECTION_CACHE: OnceLock<Mutex<BTreeMap<String, graph::CommunityResult>>> =
    OnceLock::new();

#[derive(Debug, Clone, Serialize)]
struct CommunityDetectionDiagnostics {
    cache_hit: bool,
    edge_count: usize,
    iterations: usize,
    tagpath_state: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    tagpath_stale_reason: Option<String>,
    annotated_community_count: usize,
    annotated_member_count: usize,
    ambiguous_member_count: usize,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    ambiguous_members: Vec<CommunityMemberAmbiguityDiagnostic>,
}

#[derive(Debug, Clone)]
struct CommunityDetectionReport {
    result: graph::CommunityResult,
    diagnostics: CommunityDetectionDiagnostics,
}

#[derive(Debug, Clone)]
struct CommunityTagpathCachePart {
    state: String,
    reason: Option<String>,
    key: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct CommunityDetectionCacheEntry {
    version: String,
    key: String,
    result: graph::CommunityResult,
}

fn community_detection_cache() -> &'static Mutex<BTreeMap<String, graph::CommunityResult>> {
    COMMUNITY_DETECTION_CACHE.get_or_init(|| Mutex::new(BTreeMap::new()))
}

fn community_tagpath_cache_part_for_loaded(
    adapter: &tagpath_adapter::TagpathAdapter,
) -> CommunityTagpathCachePart {
    let index_path = tagpath::index::index_path(&adapter.project_root);
    let index_hash = fs::read(&index_path)
        .map(|bytes| hash_bytes_hex(&bytes))
        .unwrap_or_else(|err| hash_bytes_hex(format!("fresh-index-unreadable:{err:#}").as_bytes()));
    CommunityTagpathCachePart {
        state: "fresh".to_string(),
        reason: None,
        key: format!("fresh:{index_hash}"),
    }
}

fn community_tagpath_cache_part(
    root: &std::path::Path,
    opts: &TagpathSearchOpts,
) -> Result<CommunityTagpathCachePart> {
    if opts.no_tagpath {
        return Ok(CommunityTagpathCachePart {
            state: "disabled".to_string(),
            reason: None,
            key: "disabled".to_string(),
        });
    }
    match tagpath_adapter::try_load(root) {
        tagpath_adapter::LoadResult::Loaded(adapter) => {
            Ok(community_tagpath_cache_part_for_loaded(&adapter))
        }
        tagpath_adapter::LoadResult::Stale { reason, .. } => {
            if opts.strict {
                anyhow::bail!(
                    "tagpath index is stale (reason={reason}); rerun `tagpath index --update` or drop --tagpath-strict"
                );
            }
            Ok(CommunityTagpathCachePart {
                state: "stale".to_string(),
                key: format!("stale:{reason}"),
                reason: Some(reason),
            })
        }
        tagpath_adapter::LoadResult::Missing => Ok(CommunityTagpathCachePart {
            state: "missing".to_string(),
            reason: None,
            key: "missing".to_string(),
        }),
    }
}

fn community_graph_watermark(db: &index::IndexDb) -> Result<String> {
    let source_snapshot = db.source_snapshot_parts()?;
    let edge_rows = db.edge_count()?;
    let symbol_rows = db.symbol_count()?;
    content_hash(&serde_json::json!({
        "source_snapshot": source_snapshot,
        "edge_rows": edge_rows,
        "symbol_rows": symbol_rows,
    }))
}

fn community_detection_cache_key(
    root: &std::path::Path,
    scope: Option<&str>,
    graph_watermark: &str,
    tagpath: &CommunityTagpathCachePart,
) -> Result<String> {
    content_hash(&serde_json::json!({
        "version": COMMUNITY_DETECTION_CACHE_VERSION,
        "root": root.display().to_string(),
        "scope": scope.unwrap_or("root"),
        "graph_watermark": graph_watermark,
        "tagpath": tagpath.key,
    }))
}

fn community_detection_cache_path(
    root: &std::path::Path,
    scope: Option<&str>,
    key: &str,
) -> PathBuf {
    root.join(".tsift/community-cache")
        .join(scope.unwrap_or("root"))
        .join(format!("{key}.json"))
}

fn read_community_detection_cache(
    root: &std::path::Path,
    scope: Option<&str>,
    key: &str,
) -> Option<graph::CommunityResult> {
    let path = community_detection_cache_path(root, scope, key);
    let bytes = fs::read(path).ok()?;
    let entry: CommunityDetectionCacheEntry = serde_json::from_slice(&bytes).ok()?;
    if entry.version == COMMUNITY_DETECTION_CACHE_VERSION && entry.key == key {
        Some(entry.result)
    } else {
        None
    }
}

fn write_community_detection_cache(
    root: &std::path::Path,
    scope: Option<&str>,
    key: &str,
    result: &graph::CommunityResult,
) {
    let path = community_detection_cache_path(root, scope, key);
    let Some(parent) = path.parent() else {
        return;
    };
    if fs::create_dir_all(parent).is_err() {
        return;
    }
    let entry = CommunityDetectionCacheEntry {
        version: COMMUNITY_DETECTION_CACHE_VERSION.to_string(),
        key: key.to_string(),
        result: result.clone(),
    };
    if let Ok(bytes) = serde_json::to_vec(&entry) {
        let _ = fs::write(path, bytes);
    }
}

fn community_detection_diagnostics(
    cache_hit: bool,
    result: &graph::CommunityResult,
    tagpath: &CommunityTagpathCachePart,
) -> CommunityDetectionDiagnostics {
    CommunityDetectionDiagnostics {
        cache_hit,
        edge_count: result.edge_count,
        iterations: result.iterations,
        tagpath_state: tagpath.state.clone(),
        tagpath_stale_reason: tagpath.reason.clone(),
        annotated_community_count: 0,
        annotated_member_count: 0,
        ambiguous_member_count: 0,
        ambiguous_members: Vec::new(),
    }
}

fn update_community_annotation_diagnostics(
    diagnostics: &mut CommunityDetectionDiagnostics,
    communities: &[graph::Community],
    annotation: Option<&TagpathAnnotationDiagnostic>,
) {
    diagnostics.annotated_community_count = communities
        .iter()
        .filter(|community| {
            community
                .members
                .iter()
                .any(|member| member.tagpath_handle.is_some())
        })
        .count();
    diagnostics.annotated_member_count = communities
        .iter()
        .flat_map(|community| community.members.iter())
        .filter(|member| member.tagpath_handle.is_some())
        .count();
    if let Some(annotation) = annotation {
        diagnostics.ambiguous_member_count = annotation.ambiguous_members.len();
        diagnostics.ambiguous_members = annotation.ambiguous_members.clone();
    } else {
        diagnostics.ambiguous_member_count = 0;
        diagnostics.ambiguous_members.clear();
    }
}

fn detect_communities_cached(
    db: &index::IndexDb,
    root: &std::path::Path,
    scope: Option<&str>,
    tagpath: &CommunityTagpathCachePart,
) -> Result<CommunityDetectionReport> {
    let graph_watermark = community_graph_watermark(db)?;
    let cache_key = community_detection_cache_key(root, scope, &graph_watermark, tagpath)?;

    if let Some(result) = community_detection_cache()
        .lock()
        .ok()
        .and_then(|cache| cache.get(&cache_key).cloned())
    {
        return Ok(CommunityDetectionReport {
            diagnostics: community_detection_diagnostics(true, &result, tagpath),
            result,
        });
    }

    if let Some(result) = read_community_detection_cache(root, scope, &cache_key) {
        if let Ok(mut cache) = community_detection_cache().lock() {
            cache.insert(cache_key.clone(), result.clone());
        }
        return Ok(CommunityDetectionReport {
            diagnostics: community_detection_diagnostics(true, &result, tagpath),
            result,
        });
    }

    let edges = db.all_edges()?;
    let result = graph::detect_communities(&edges);
    write_community_detection_cache(root, scope, &cache_key, &result);
    if let Ok(mut cache) = community_detection_cache().lock() {
        cache.insert(cache_key, result.clone());
    }
    Ok(CommunityDetectionReport {
        diagnostics: community_detection_diagnostics(false, &result, tagpath),
        result,
    })
}

/// Annotate symbol hits in-place with `tagpath_handle` when a fresh tagpath
/// index is present at `root`. Returns a diagnostic describing whether the
/// adapter loaded, missed, or fell back due to staleness.
///
/// Behavior matrix:
///
/// | `no_tagpath` | index state | strict | action |
/// |---|---|---|---|
/// | true        | any         | any     | no-op |
/// | false       | missing     | any     | no-op |
/// | false       | fresh       | any     | annotate hits |
/// | false       | stale       | false   | emit diagnostic, no annotation |
/// | false       | stale       | true    | return error |
pub fn annotate_hits_with_tagpath(
    hits: &mut [index::SymbolHit],
    root: &std::path::Path,
    opts: &TagpathSearchOpts,
) -> Result<TagpathAnnotationDiagnostic> {
    if opts.no_tagpath {
        return Ok(TagpathAnnotationDiagnostic::default());
    }
    match tagpath_adapter::try_load(root) {
        tagpath_adapter::LoadResult::Loaded(adapter) => {
            for hit in hits.iter_mut() {
                let abs = if std::path::Path::new(&hit.file).is_absolute() {
                    std::path::PathBuf::from(&hit.file)
                } else {
                    root.join(&hit.file)
                };
                if let Some(handle) = adapter.handle_for_member(&abs, &hit.name) {
                    hit.tagpath_handle = Some(handle);
                }
            }
            Ok(TagpathAnnotationDiagnostic {
                stale: false,
                reason: None,
                loaded: true,
                ambiguous_members: Vec::new(),
            })
        }
        tagpath_adapter::LoadResult::Stale { reason, .. } => {
            if opts.strict {
                anyhow::bail!(
                    "tagpath index is stale (reason={reason}); rerun `tagpath index --update` or drop --tagpath-strict"
                );
            }
            Ok(TagpathAnnotationDiagnostic {
                stale: true,
                reason: Some(reason),
                loaded: false,
                ambiguous_members: Vec::new(),
            })
        }
        tagpath_adapter::LoadResult::Missing => Ok(TagpathAnnotationDiagnostic::default()),
    }
}

fn index_file_abs(file: &str, root: &std::path::Path) -> std::path::PathBuf {
    if std::path::Path::new(file).is_absolute() {
        std::path::PathBuf::from(file)
    } else {
        root.join(file)
    }
}

fn index_file_key(file: &str, root: &std::path::Path) -> String {
    let path = std::path::Path::new(file);
    let rel = if path.is_absolute() {
        path.strip_prefix(root).unwrap_or(path)
    } else {
        path
    };
    rel.to_string_lossy().replace('\\', "/")
}

fn tagpath_handle_for_index_file(
    file: &str,
    name: &str,
    root: &std::path::Path,
    adapter: &tagpath_adapter::TagpathAdapter,
) -> Option<String> {
    adapter.handle_for_member(&index_file_abs(file, root), name)
}

#[derive(Debug, Clone)]
struct TagpathHandleCandidate {
    file: String,
    line: i64,
    handle: String,
}

fn tagpath_handle_candidates_for_symbol_rows(
    name: &str,
    syms: &[index::StoredSymbol],
    root: &std::path::Path,
    adapter: &tagpath_adapter::TagpathAdapter,
) -> Vec<TagpathHandleCandidate> {
    syms.iter()
        .filter_map(|sym| {
            let handle = tagpath_handle_for_index_file(&sym.file, name, root, adapter)?;
            Some(TagpathHandleCandidate {
                file: index_file_key(&sym.file, root),
                line: sym.line,
                handle,
            })
        })
        .collect()
}

fn file_communities_from_callers(
    db: &index::IndexDb,
    root: &std::path::Path,
    scope: Option<&str>,
    tagpath: &CommunityTagpathCachePart,
) -> Result<std::collections::HashMap<String, std::collections::HashSet<usize>>> {
    let community_report = detect_communities_cached(db, root, scope, tagpath)?;
    if community_report.result.communities.is_empty() {
        return Ok(std::collections::HashMap::new());
    }
    let mut community_by_symbol = std::collections::HashMap::new();
    for community in community_report.result.communities {
        for member in community.members {
            community_by_symbol.insert(member.name, community.id);
        }
    }

    let mut communities_by_file: std::collections::HashMap<
        String,
        std::collections::HashSet<usize>,
    > = std::collections::HashMap::new();
    for sym in db.all_symbols()? {
        if let Some(community_id) = community_by_symbol.get(&sym.name) {
            communities_by_file
                .entry(index_file_key(&sym.file, root))
                .or_default()
                .insert(*community_id);
        }
    }
    for edge in db.all_stored_edges()? {
        if let Some(community_id) = community_by_symbol.get(&edge.caller_name) {
            communities_by_file
                .entry(index_file_key(&edge.caller_file, root))
                .or_default()
                .insert(*community_id);
        }
    }
    Ok(communities_by_file)
}

fn resolve_tagpath_handle_for_callee_edge(
    edge: &index::StoredEdge,
    db: &index::IndexDb,
    root: &std::path::Path,
    adapter: &tagpath_adapter::TagpathAdapter,
    communities_by_file: &std::collections::HashMap<String, std::collections::HashSet<usize>>,
) -> Option<String> {
    let syms = db.symbol_info(&edge.callee_name).ok()?;
    let candidates =
        tagpath_handle_candidates_for_symbol_rows(&edge.callee_name, &syms, root, adapter);
    let caller_file = index_file_key(&edge.caller_file, root);

    if let Some(candidate) = candidates
        .iter()
        .find(|candidate| candidate.file == caller_file)
    {
        return Some(candidate.handle.clone());
    }

    if let Some(caller_communities) = communities_by_file.get(&caller_file) {
        for candidate in &candidates {
            if let Some(candidate_communities) = communities_by_file.get(&candidate.file)
                && !caller_communities.is_disjoint(candidate_communities)
            {
                return Some(candidate.handle.clone());
            }
        }
    }

    candidates.first().map(|candidate| candidate.handle.clone())
}

fn push_bounded_community_member_ref(
    refs_by_member: &mut HashMap<(usize, String), Vec<graph::CommunityMemberRef>>,
    community_id: usize,
    name: &str,
    reference: graph::CommunityMemberRef,
) {
    let refs = refs_by_member
        .entry((community_id, name.to_string()))
        .or_default();
    if refs.iter().any(|existing| {
        existing.file == reference.file
            && existing.line == reference.line
            && existing.role == reference.role
            && existing.peer == reference.peer
    }) {
        return;
    }
    if refs.len() < 6 {
        refs.push(reference);
    }
}

fn choose_symbol_row_by_files<'a>(
    syms: &'a [index::StoredSymbol],
    files: &BTreeSet<String>,
    root: &std::path::Path,
) -> Option<(&'a index::StoredSymbol, &'static str)> {
    let matches: Vec<&index::StoredSymbol> = syms
        .iter()
        .filter(|sym| files.contains(&index_file_key(&sym.file, root)))
        .collect();
    if matches.len() == 1 {
        Some((matches[0], "edge_file"))
    } else {
        None
    }
}

fn choose_tagpath_candidate_by_files<'a>(
    candidates: &'a [TagpathHandleCandidate],
    files: &BTreeSet<String>,
    evidence: &'static str,
) -> Option<(&'a TagpathHandleCandidate, &'static str)> {
    let matches: Vec<&TagpathHandleCandidate> = candidates
        .iter()
        .filter(|candidate| files.contains(&candidate.file))
        .collect();
    if matches.len() == 1 {
        Some((matches[0], evidence))
    } else {
        None
    }
}

fn annotate_community_members_with_context(
    communities: &mut [graph::Community],
    db: &index::IndexDb,
    root: &std::path::Path,
    adapter: Option<&tagpath_adapter::TagpathAdapter>,
) -> Result<Vec<CommunityMemberAmbiguityDiagnostic>> {
    let mut community_by_name = HashMap::<String, usize>::new();
    for community in communities.iter() {
        for member in &community.members {
            community_by_name.insert(member.name.clone(), community.id);
        }
    }

    let mut symbols_by_name = HashMap::<String, Vec<index::StoredSymbol>>::new();
    for sym in db.all_symbols()? {
        symbols_by_name
            .entry(sym.name.clone())
            .or_default()
            .push(sym);
    }

    let mut refs_by_member = HashMap::<(usize, String), Vec<graph::CommunityMemberRef>>::new();
    let mut evidence_files_by_member = HashMap::<(usize, String), BTreeSet<String>>::new();
    let mut context_files_by_community = HashMap::<usize, BTreeSet<String>>::new();

    for edge in db.all_stored_edges()? {
        let Some(&caller_community) = community_by_name.get(&edge.caller_name) else {
            continue;
        };
        let Some(&callee_community) = community_by_name.get(&edge.callee_name) else {
            continue;
        };
        if caller_community != callee_community {
            continue;
        }

        let file = index_file_key(&edge.caller_file, root);
        context_files_by_community
            .entry(caller_community)
            .or_default()
            .insert(file.clone());

        evidence_files_by_member
            .entry((caller_community, edge.caller_name.clone()))
            .or_default()
            .insert(file.clone());
        push_bounded_community_member_ref(
            &mut refs_by_member,
            caller_community,
            &edge.caller_name,
            graph::CommunityMemberRef {
                file: file.clone(),
                line: edge.caller_line,
                role: "caller".to_string(),
                peer: edge.callee_name.clone(),
            },
        );

        evidence_files_by_member
            .entry((callee_community, edge.callee_name.clone()))
            .or_default()
            .insert(file.clone());
        push_bounded_community_member_ref(
            &mut refs_by_member,
            callee_community,
            &edge.callee_name,
            graph::CommunityMemberRef {
                file,
                line: edge.call_site_line,
                role: "callee".to_string(),
                peer: edge.caller_name.clone(),
            },
        );
    }

    let mut diagnostics = Vec::new();
    for community in communities.iter_mut() {
        let community_files = context_files_by_community
            .get(&community.id)
            .cloned()
            .unwrap_or_default();
        for member in community.members.iter_mut() {
            member.file = None;
            member.line = None;
            member.tagpath_handle = None;
            let key = (community.id, member.name.clone());
            member.refs = refs_by_member.remove(&key).unwrap_or_default();

            let syms = symbols_by_name
                .get(&member.name)
                .map(Vec::as_slice)
                .unwrap_or(&[]);
            let evidence_files = evidence_files_by_member
                .get(&key)
                .cloned()
                .unwrap_or_default();
            let candidates = adapter
                .map(|adapter| {
                    tagpath_handle_candidates_for_symbol_rows(&member.name, syms, root, adapter)
                })
                .unwrap_or_default();

            let mut selected_file: Option<String> = None;
            let mut selected_line: Option<i64> = None;
            let mut selected_handle: Option<String> = None;
            let mut selected_evidence: Option<&'static str> = None;

            if let Some(candidate) = candidates.first().filter(|_| candidates.len() == 1) {
                selected_file = Some(candidate.file.clone());
                selected_line = Some(candidate.line);
                selected_handle = Some(candidate.handle.clone());
                selected_evidence = Some("unique_tagpath_handle");
            } else if let Some((candidate, evidence)) =
                choose_tagpath_candidate_by_files(&candidates, &evidence_files, "edge_file")
            {
                selected_file = Some(candidate.file.clone());
                selected_line = Some(candidate.line);
                selected_handle = Some(candidate.handle.clone());
                selected_evidence = Some(evidence);
            } else if let Some((candidate, evidence)) =
                choose_tagpath_candidate_by_files(&candidates, &community_files, "community_file")
            {
                selected_file = Some(candidate.file.clone());
                selected_line = Some(candidate.line);
                selected_handle = Some(candidate.handle.clone());
                selected_evidence = Some(evidence);
            }

            if selected_file.is_none() {
                if let Some(sym) = syms.first().filter(|_| syms.len() == 1) {
                    selected_file = Some(index_file_key(&sym.file, root));
                    selected_line = Some(sym.line);
                    selected_evidence = Some("unique_symbol_row");
                } else if let Some((sym, evidence)) =
                    choose_symbol_row_by_files(syms, &evidence_files, root)
                {
                    selected_file = Some(index_file_key(&sym.file, root));
                    selected_line = Some(sym.line);
                    selected_evidence = Some(evidence);
                } else if let Some((sym, _)) =
                    choose_symbol_row_by_files(syms, &community_files, root)
                {
                    selected_file = Some(index_file_key(&sym.file, root));
                    selected_line = Some(sym.line);
                    selected_evidence = Some("community_file");
                }
            }

            member.file = selected_file.clone();
            member.line = selected_line;
            member.tagpath_handle = selected_handle;

            if syms.len() > 1 || candidates.len() > 1 {
                diagnostics.push(CommunityMemberAmbiguityDiagnostic {
                    community_id: community.id,
                    name: member.name.clone(),
                    candidate_count: syms.len(),
                    tagpath_candidate_count: candidates.len(),
                    evidence: selected_evidence
                        .unwrap_or("ambiguous_no_evidence")
                        .to_string(),
                    chosen_file: selected_file,
                });
            }
        }
    }

    Ok(diagnostics)
}

/// Annotate `StoredSymbol` definitions in-place with `tagpath_handle` when
/// a fresh tagpath index is present at `root`. Same fallback matrix as
/// [`annotate_hits_with_tagpath`].
pub fn annotate_stored_symbols_with_tagpath(
    symbols: &mut [index::StoredSymbol],
    root: &std::path::Path,
    opts: &TagpathSearchOpts,
) -> Result<TagpathAnnotationDiagnostic> {
    if opts.no_tagpath {
        return Ok(TagpathAnnotationDiagnostic::default());
    }
    match tagpath_adapter::try_load(root) {
        tagpath_adapter::LoadResult::Loaded(adapter) => {
            for sym in symbols.iter_mut() {
                let abs = if std::path::Path::new(&sym.file).is_absolute() {
                    std::path::PathBuf::from(&sym.file)
                } else {
                    root.join(&sym.file)
                };
                if let Some(handle) = adapter.handle_for_member(&abs, &sym.name) {
                    sym.tagpath_handle = Some(handle);
                }
            }
            Ok(TagpathAnnotationDiagnostic {
                stale: false,
                reason: None,
                loaded: true,
                ambiguous_members: Vec::new(),
            })
        }
        tagpath_adapter::LoadResult::Stale { reason, .. } => {
            if opts.strict {
                anyhow::bail!(
                    "tagpath index is stale (reason={reason}); rerun `tagpath index --update` or drop --tagpath-strict"
                );
            }
            Ok(TagpathAnnotationDiagnostic {
                stale: true,
                reason: Some(reason),
                loaded: false,
                ambiguous_members: Vec::new(),
            })
        }
        tagpath_adapter::LoadResult::Missing => Ok(TagpathAnnotationDiagnostic::default()),
    }
}

/// Annotate `StoredEdge` rows in-place with `tagpath_handle` from the
/// tagpath index. The handle names whichever endpoint the consumer cares
/// about: pass `EdgeSide::Caller` for caller rows (uses `caller_file` +
/// `caller_name` directly) and `EdgeSide::Callee` for callee rows
/// (resolves each callee edge via `db.symbol_info`, preferring the
/// caller's file or community before the no-context first-handle fallback).
pub fn annotate_stored_edges_with_tagpath(
    edges: &mut [index::StoredEdge],
    db: &index::IndexDb,
    root: &std::path::Path,
    scope: Option<&str>,
    side: EdgeSide,
    opts: &TagpathSearchOpts,
) -> Result<TagpathAnnotationDiagnostic> {
    if opts.no_tagpath {
        return Ok(TagpathAnnotationDiagnostic::default());
    }
    match tagpath_adapter::try_load(root) {
        tagpath_adapter::LoadResult::Loaded(adapter) => {
            match side {
                EdgeSide::Caller => {
                    for edge in edges.iter_mut() {
                        let abs = if std::path::Path::new(&edge.caller_file).is_absolute() {
                            std::path::PathBuf::from(&edge.caller_file)
                        } else {
                            root.join(&edge.caller_file)
                        };
                        if let Some(handle) = adapter.handle_for_member(&abs, &edge.caller_name) {
                            edge.tagpath_handle = Some(handle);
                        }
                    }
                }
                EdgeSide::Callee => {
                    let tagpath = community_tagpath_cache_part_for_loaded(&adapter);
                    let communities_by_file =
                        file_communities_from_callers(db, root, scope, &tagpath)
                            .unwrap_or_default();
                    for edge in edges.iter_mut() {
                        if let Some(handle) = resolve_tagpath_handle_for_callee_edge(
                            edge,
                            db,
                            root,
                            &adapter,
                            &communities_by_file,
                        ) {
                            edge.tagpath_handle = Some(handle);
                        }
                    }
                }
            }
            Ok(TagpathAnnotationDiagnostic {
                stale: false,
                reason: None,
                loaded: true,
                ambiguous_members: Vec::new(),
            })
        }
        tagpath_adapter::LoadResult::Stale { reason, .. } => {
            if opts.strict {
                anyhow::bail!(
                    "tagpath index is stale (reason={reason}); rerun `tagpath index --update` or drop --tagpath-strict"
                );
            }
            Ok(TagpathAnnotationDiagnostic {
                stale: true,
                reason: Some(reason),
                loaded: false,
                ambiguous_members: Vec::new(),
            })
        }
        tagpath_adapter::LoadResult::Missing => Ok(TagpathAnnotationDiagnostic::default()),
    }
}

/// Which endpoint of a `StoredEdge` is the row's primary symbol — caller
/// (caller list) or callee (callee list).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EdgeSide {
    Caller,
    Callee,
}

/// Annotate every `graph::CommunityMember` in `communities` in-place with
/// file/ref context and, when available, the stable `mem:` handle from the
/// tagpath index. Duplicate names are resolved through edge/community
/// evidence rather than a name-only first-row fallback.
pub fn annotate_communities_with_tagpath(
    communities: &mut [graph::Community],
    db: &index::IndexDb,
    root: &std::path::Path,
    opts: &TagpathSearchOpts,
) -> Result<Option<TagpathAnnotationDiagnostic>> {
    if opts.no_tagpath {
        annotate_community_members_with_context(communities, db, root, None)?;
        return Ok(None);
    }
    match tagpath_adapter::try_load(root) {
        tagpath_adapter::LoadResult::Loaded(adapter) => {
            let ambiguous_members =
                annotate_community_members_with_context(communities, db, root, Some(&adapter))?;
            Ok(Some(TagpathAnnotationDiagnostic {
                stale: false,
                reason: None,
                loaded: true,
                ambiguous_members,
            }))
        }
        tagpath_adapter::LoadResult::Stale { reason, .. } => {
            if opts.strict {
                anyhow::bail!(
                    "tagpath index is stale (reason={reason}); rerun `tagpath index --update` or drop --tagpath-strict"
                );
            }
            let ambiguous_members =
                annotate_community_members_with_context(communities, db, root, None)?;
            Ok(Some(TagpathAnnotationDiagnostic {
                stale: true,
                reason: Some(reason),
                loaded: false,
                ambiguous_members,
            }))
        }
        tagpath_adapter::LoadResult::Missing => {
            annotate_community_members_with_context(communities, db, root, None)?;
            Ok(None)
        }
    }
}

/// Annotate `graph::PathNode` entries in-place with `tagpath_handle` when a
/// fresh tagpath index is present at `root`. Symbol→file resolution goes
/// through `db.symbol_info(name)` (first definition wins), then the adapter
/// resolves the per-member handle. Same fallback matrix as
/// [`annotate_hits_with_tagpath`].
pub fn annotate_path_nodes_with_tagpath(
    nodes: &mut [graph::PathNode],
    db: &index::IndexDb,
    root: &std::path::Path,
    opts: &TagpathSearchOpts,
) -> Result<TagpathAnnotationDiagnostic> {
    if opts.no_tagpath {
        return Ok(TagpathAnnotationDiagnostic::default());
    }
    match tagpath_adapter::try_load(root) {
        tagpath_adapter::LoadResult::Loaded(adapter) => {
            for node in nodes.iter_mut() {
                let syms = match db.symbol_info(&node.name) {
                    Ok(v) => v,
                    Err(_) => continue,
                };
                let Some(sym) = syms.into_iter().next() else {
                    continue;
                };
                let abs = if std::path::Path::new(&sym.file).is_absolute() {
                    std::path::PathBuf::from(&sym.file)
                } else {
                    root.join(&sym.file)
                };
                if let Some(handle) = adapter.handle_for_member(&abs, &node.name) {
                    node.tagpath_handle = Some(handle);
                }
            }
            Ok(TagpathAnnotationDiagnostic {
                stale: false,
                reason: None,
                loaded: true,
                ambiguous_members: Vec::new(),
            })
        }
        tagpath_adapter::LoadResult::Stale { reason, .. } => {
            if opts.strict {
                anyhow::bail!(
                    "tagpath index is stale (reason={reason}); rerun `tagpath index --update` or drop --tagpath-strict"
                );
            }
            Ok(TagpathAnnotationDiagnostic {
                stale: true,
                reason: Some(reason),
                loaded: false,
                ambiguous_members: Vec::new(),
            })
        }
        tagpath_adapter::LoadResult::Missing => Ok(TagpathAnnotationDiagnostic::default()),
    }
}

const JSON_PATH_KEYS: &[&str] = &["file", "path", "caller_file", "file_path"];

fn relativize_json_paths(val: &mut serde_json::Value, root: &std::path::Path) {
    let root_str = root.to_string_lossy();
    let prefix = format!("{}/", root_str.trim_end_matches('/'));
    relativize_json_inner(val, &prefix);
}

fn relativize_json_inner(val: &mut serde_json::Value, prefix: &str) {
    match val {
        serde_json::Value::Array(arr) => {
            for v in arr {
                relativize_json_inner(v, prefix);
            }
        }
        serde_json::Value::Object(map) => {
            for (k, v) in map.iter_mut() {
                if JSON_PATH_KEYS.contains(&k.as_str())
                    && let serde_json::Value::String(s) = v
                    && let Some(rest) = s.strip_prefix(prefix)
                {
                    *s = rest.to_string();
                }
                relativize_json_inner(v, prefix);
            }
        }
        _ => {}
    }
}

fn format_score(score: f64, compact: bool) -> String {
    if compact {
        format!("{score:.2}")
    } else {
        format!("{score:.4}")
    }
}

fn truncate_for_compact(input: &str, max_chars: usize) -> String {
    let trimmed = input.trim();
    let count = trimmed.chars().count();
    if count <= max_chars {
        return trimmed.to_string();
    }
    let prefix: String = trimmed.chars().take(max_chars.saturating_sub(3)).collect();
    format!("{prefix}...")
}

fn compact_snippet(snippet: &str) -> Option<String> {
    snippet
        .lines()
        .find(|line| !line.trim().is_empty())
        .map(|line| truncate_for_compact(line, 100))
}

fn compact_members(members: &[graph::CommunityMember], limit: usize) -> String {
    let names: Vec<&str> = members.iter().map(|m| m.name.as_str()).collect();
    if names.len() <= limit {
        return names.join(", ");
    }
    format!(
        "{} (+{} more)",
        names[..limit].join(", "),
        names.len() - limit
    )
}

const DEFAULT_BUDGET_ITEMS: usize = 5;
const DEFAULT_BUDGET_BYTES: usize = 160;
const DEFAULT_FOLLOW_UP_ITEMS: usize = 4;

fn stable_handle(prefix: &str, key: &str) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(prefix.as_bytes());
    hasher.update(&[0]);
    hasher.update(key.as_bytes());
    let hex = hasher.finalize().to_hex();
    format!("{prefix}-{}", &hex[..10])
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CanonicalTagFamily {
    canonical: String,
    tag_alias: String,
}

fn canonical_family_from_tagpath_family(
    family: tagpath_family::TagFamily,
) -> Option<CanonicalTagFamily> {
    let tag_alias = if family.dimensions.is_empty() {
        family.tags.join("/")
    } else {
        family
            .dimensions
            .iter()
            .filter(|dimension| !dimension.tags.is_empty())
            .map(|dimension| dimension.tags.join("."))
            .collect::<Vec<_>>()
            .join("/")
    };

    if tag_alias.is_empty() {
        None
    } else {
        Some(CanonicalTagFamily {
            canonical: family.canonical,
            tag_alias,
        })
    }
}

fn canonical_tag_family_from_name(name: &str) -> Option<CanonicalTagFamily> {
    let trimmed = name.trim();
    if trimmed.is_empty() {
        return None;
    }

    canonical_family_from_tagpath_family(tagpath_family::generate_family(trimmed))
}

fn canonical_tag_family_from_tags(tags: &str) -> Option<CanonicalTagFamily> {
    let canonical = tags
        .split(',')
        .map(str::trim)
        .filter(|tag| !tag.is_empty())
        .collect::<Vec<_>>()
        .join("_");
    if canonical.is_empty() {
        None
    } else {
        canonical_family_from_tagpath_family(tagpath_family::generate_family(&canonical))
    }
}

fn canonical_tag_family_from_symbol(name: &str, tags: Option<&str>) -> Option<CanonicalTagFamily> {
    tags.and_then(canonical_tag_family_from_tags)
        .or_else(|| canonical_tag_family_from_name(name))
}

fn tag_alias_from_name(name: &str) -> Option<String> {
    canonical_tag_family_from_name(name).map(|family| family.tag_alias)
}

fn tag_alias_from_tags(name: &str, tags: Option<&str>) -> Option<String> {
    canonical_tag_family_from_symbol(name, tags).map(|family| family.tag_alias)
}

fn family_query_from_tag_alias(tag_alias: &str) -> Option<String> {
    let query = tag_alias
        .split(['/', '.'])
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    if query.is_empty() { None } else { Some(query) }
}

#[derive(Serialize, Clone, Debug, PartialEq, Eq)]
struct CompactOntologyRefPreview {
    handle: String,
    tag: String,
    path: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    title: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    domain: Option<String>,
}

#[derive(Clone, Debug)]
struct TagOntologyPreviewContext {
    project_root: PathBuf,
    tags: BTreeMap<String, tagpath_ontology::OntologyTag>,
}

#[derive(Serialize, Clone, Debug, PartialEq, Eq)]
struct CompactSymbolRefPreview {
    handle: String,
    name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    tag_alias: Option<String>,
    #[serde(skip_serializing_if = "Vec::is_empty", default)]
    ontology_refs: Vec<CompactOntologyRefPreview>,
}

fn build_compact_symbol_ref(
    prefix: &str,
    key: &str,
    name: &str,
    tags: Option<&str>,
    max_bytes: usize,
) -> CompactSymbolRefPreview {
    build_compact_symbol_ref_with_ontology(prefix, key, name, tags, max_bytes, None)
}

fn build_compact_symbol_ref_with_ontology(
    prefix: &str,
    key: &str,
    name: &str,
    tags: Option<&str>,
    max_bytes: usize,
    ontology: Option<&TagOntologyPreviewContext>,
) -> CompactSymbolRefPreview {
    let tag_alias = tag_alias_from_tags(name, tags);
    let ontology_refs = tag_alias
        .as_deref()
        .map(|alias| ontology_refs_for_alias(ontology, alias))
        .unwrap_or_default();
    CompactSymbolRefPreview {
        handle: stable_handle(prefix, key),
        name: truncate_for_budget(name, max_bytes),
        tag_alias: tag_alias.map(|alias| truncate_for_budget(&alias, max_bytes)),
        ontology_refs,
    }
}

fn load_tag_ontology_preview_context(root: &Path) -> Option<TagOntologyPreviewContext> {
    let report = tagpath_ontology::load_project(root).ok()?;
    if report.tags.is_empty() {
        return None;
    }
    Some(TagOntologyPreviewContext {
        project_root: report.project_path,
        tags: report
            .tags
            .into_iter()
            .map(|tag| (tag.tag.clone(), tag))
            .collect(),
    })
}

fn ontology_refs_for_alias(
    ontology: Option<&TagOntologyPreviewContext>,
    alias: &str,
) -> Vec<CompactOntologyRefPreview> {
    let Some(ontology) = ontology else {
        return Vec::new();
    };
    let mut seen = BTreeSet::new();
    alias
        .split('/')
        .flat_map(|part| part.split('.'))
        .map(str::trim)
        .filter(|tag| !tag.is_empty())
        .filter_map(|tag| {
            let key = tag.to_ascii_lowercase();
            if !seen.insert(key.clone()) {
                return None;
            }
            let ontology_tag = ontology.tags.get(&key)?;
            let path = relativize_ontology_path(&ontology_tag.path, &ontology.project_root);
            Some(CompactOntologyRefPreview {
                handle: stable_handle("tont", &format!("{}:{path}", ontology_tag.tag)),
                tag: ontology_tag.tag.clone(),
                path,
                title: ontology_tag.title.clone(),
                domain: ontology_tag.domain.clone(),
            })
        })
        .collect()
}

fn relativize_ontology_path(path: &Path, root: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or(path)
        .to_string_lossy()
        .replace('\\', "/")
}

fn format_symbol_preview_line(handle: &str, name: &str, tag_alias: Option<&str>) -> String {
    match tag_alias {
        Some(alias) => format!("{handle} {name} tag:{alias}"),
        None => format!("{handle} {name}"),
    }
}

fn format_summary_ref_line(summary: &ContextPackSummaryRefPreview) -> String {
    match summary.tag_alias.as_deref() {
        Some(alias) => format!(
            "{} {} tag:{} expand:{}",
            summary.handle, summary.symbol, alias, summary.expand
        ),
        None => format!(
            "{} {} expand:{}",
            summary.handle, summary.symbol, summary.expand
        ),
    }
}

fn compact_symbol_ref_token(symbol: &CompactSymbolRefPreview) -> String {
    match symbol.tag_alias.as_deref() {
        Some(alias) => format!("{}@{}", symbol.handle, alias),
        None => format!("{}@{}", symbol.handle, symbol.name),
    }
}

fn truncate_for_budget(input: &str, max_bytes: usize) -> String {
    let trimmed = input.trim();
    if trimmed.len() <= max_bytes {
        return trimmed.to_string();
    }
    if max_bytes <= 3 {
        return ".".repeat(max_bytes);
    }

    let mut end = 0usize;
    for (idx, ch) in trimmed.char_indices() {
        let next = idx + ch.len_utf8();
        if next > max_bytes.saturating_sub(3) {
            break;
        }
        end = next;
    }

    if end == 0 {
        "...".to_string()
    } else {
        format!("{}...", &trimmed[..end])
    }
}

fn abbreviate_kind(kind: &str) -> &str {
    match kind {
        "function" => "fn",
        "method" => "meth",
        "module" | "mod" => "mod",
        "struct" => "struct",
        "trait" => "trait",
        "impl" => "impl",
        "class" => "cls",
        "interface" => "iface",
        "type_alias" => "type",
        "data_class" => "data_cls",
        "sealed_class" => "sealed_cls",
        "enum_class" => "enum_cls",
        "companion_object" => "comp_obj",
        "object" => "obj",
        "heading" => "h",
        "code_block" => "code",
        "alias" => "alias",
        other => other,
    }
}

fn abbreviate_match_type(mt: &str) -> &str {
    match mt {
        "exact_name" => "exact",
        "all_tags" => "all_tags",
        "partial_tags" => "partial",
        other => other,
    }
}

fn symbol_path_summary(path: &[graph::PathNode]) -> String {
    path.iter()
        .map(|n| n.name.as_str())
        .collect::<Vec<_>>()
        .join(" -> ")
}

const SEARCH_GROUP_SAMPLE_LIMIT: usize = 2;

struct SearchHitGroup {
    path: String,
    first_rank: usize,
    top_score: f64,
    confidence: String,
    hits: usize,
    samples: Vec<String>,
}

fn format_search_sample(hit: &sift::SearchHit) -> Option<String> {
    let snippet = compact_snippet(&hit.snippet)?;
    Some(match hit.location.as_deref() {
        Some(location) => format!("{location}: {snippet}"),
        None => snippet,
    })
}

fn group_search_hits(hits: &[sift::SearchHit], root: &Path, absolute: bool) -> Vec<SearchHitGroup> {
    let mut positions = BTreeMap::new();
    let mut groups = Vec::new();
    for hit in hits {
        let path = if absolute {
            hit.path.clone()
        } else {
            relativize(&hit.path, root)
        };
        let entry = positions.entry(path.clone()).or_insert_with(|| {
            groups.push(SearchHitGroup {
                path: path.clone(),
                first_rank: hit.rank,
                top_score: hit.score,
                confidence: format!("{:?}", hit.confidence),
                hits: 0,
                samples: Vec::new(),
            });
            groups.len() - 1
        });
        let group = &mut groups[*entry];
        group.hits += 1;
        if hit.rank < group.first_rank {
            group.first_rank = hit.rank;
        }
        if hit.score > group.top_score {
            group.top_score = hit.score;
        }
        if let Some(sample) = format_search_sample(hit)
            && group.samples.len() < SEARCH_GROUP_SAMPLE_LIMIT
            && !group.samples.contains(&sample)
        {
            group.samples.push(sample);
        }
    }
    groups.sort_by_key(|group| group.first_rank);
    groups
}

fn should_collapse_search_hits(hits: &[sift::SearchHit], root: &Path, absolute: bool) -> bool {
    let groups = group_search_hits(hits, root, absolute);
    let max_hits_per_file = groups.iter().map(|group| group.hits).max().unwrap_or(0);
    max_hits_per_file >= 3 || (hits.len() >= 6 && groups.len() < hits.len())
}

fn format_edge_groups(edges: &[index::StoredEdge], use_callers: bool) -> Vec<String> {
    let mut grouped: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for edge in edges {
        let key = edge.caller_file.as_str();
        let name = if use_callers {
            edge.caller_name.as_str()
        } else {
            edge.callee_name.as_str()
        };
        let names = grouped.entry(key).or_default();
        if !names.contains(&name) {
            names.push(name);
        }
    }

    grouped
        .into_iter()
        .map(|(file, names)| format!("  {} ({}): {}", file, names.len(), names.join(", ")))
        .collect()
}

fn should_collapse_edge_groups(edges: &[index::StoredEdge]) -> bool {
    let mut grouped: BTreeMap<&str, usize> = BTreeMap::new();
    for edge in edges {
        *grouped.entry(edge.caller_file.as_str()).or_default() += 1;
    }
    let max_hits_per_file = grouped.values().copied().max().unwrap_or(0);
    max_hits_per_file >= 3 || (edges.len() >= 6 && grouped.len() < edges.len())
}

/// Apply a single edit operation to file contents. Returns new content.
pub(crate) fn apply_edit_op(content: &str, op: &EditOp) -> Result<(String, usize)> {
    if op.old == op.new {
        bail!("old and new strings are identical");
    }
    let count = content.matches(op.old.as_str()).count();
    if count == 0 {
        bail!("old_string not found");
    }
    if count > 1 && !op.replace_all {
        bail!(
            "old_string matches {} times (use replace_all or provide more context)",
            count
        );
    }
    let replaced = if op.replace_all {
        content.replace(op.old.as_str(), &op.new)
    } else {
        content.replacen(op.old.as_str(), &op.new, 1)
    };
    Ok((replaced, count))
}

fn build_edit_plan(batch: &EditBatch) -> Result<Vec<PlannedEdit>> {
    let mut plan = Vec::with_capacity(batch.edits.len());
    for (i, op) in batch.edits.iter().enumerate() {
        let content = fs::read_to_string(&op.file)
            .with_context(|| format!("edit #{}: reading {}", i + 1, op.file.display()))?;
        let (replaced, count) = apply_edit_op(&content, op)
            .with_context(|| format!("edit #{}: {}", i + 1, op.file.display()))?;
        plan.push(PlannedEdit {
            index: i,
            file: op.file.clone(),
            new_content: replaced,
            replacements: count,
        });
    }
    Ok(plan)
}

fn stage_edit_plan(plan: Vec<PlannedEdit>) -> Result<Vec<StagedEdit>> {
    let mut staged = Vec::with_capacity(plan.len());
    for planned in plan {
        let parent = planned.file.parent().unwrap_or_else(|| Path::new("."));
        let mut staged_file = NamedTempFile::new_in(parent)
            .with_context(|| format!("staging {}", planned.file.display()))?;
        staged_file
            .write_all(planned.new_content.as_bytes())
            .with_context(|| format!("staging {}", planned.file.display()))?;
        staged_file
            .as_file_mut()
            .sync_all()
            .with_context(|| format!("flushing staged edit for {}", planned.file.display()))?;
        staged.push(StagedEdit {
            index: planned.index,
            file: planned.file,
            replacements: planned.replacements,
            staged_file,
        });
    }
    Ok(staged)
}

fn edit_backup_path(file: &Path, index: usize) -> PathBuf {
    let parent = file.parent().unwrap_or_else(|| Path::new("."));
    let name = file
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .unwrap_or_else(|| "edit-target".to_string());
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    parent.join(format!(
        ".{name}.tsift-edit-{stamp}-{}-{index}.bak",
        std::process::id()
    ))
}

fn rollback_applied_edits(applied: &[AppliedEdit]) -> Result<()> {
    let mut rollback_errors = Vec::new();
    for entry in applied.iter().rev() {
        if let Err(err) = fs::remove_file(&entry.file)
            && err.kind() != std::io::ErrorKind::NotFound
        {
            rollback_errors.push(format!(
                "removing {} during rollback: {}",
                entry.file.display(),
                err
            ));
            continue;
        }
        if let Err(err) = fs::rename(&entry.backup_path, &entry.file) {
            rollback_errors.push(format!(
                "restoring {} during rollback: {}",
                entry.file.display(),
                err
            ));
        }
    }
    if rollback_errors.is_empty() {
        Ok(())
    } else {
        bail!(rollback_errors.join("; "));
    }
}

fn cleanup_edit_backups(applied: &[AppliedEdit]) {
    for entry in applied {
        let _ = fs::remove_file(&entry.backup_path);
    }
}

fn ok_results_from_applied(applied: &[AppliedEdit]) -> Vec<EditResult> {
    applied
        .iter()
        .map(|entry| EditResult {
            file: entry.file.clone(),
            status: EditStatus::Ok,
            error: None,
            replacements: Some(entry.replacements),
        })
        .collect()
}

fn apply_edit_plan_atomically(plan: Vec<PlannedEdit>) -> Result<Vec<EditResult>> {
    apply_edit_plan_atomically_inner(plan, |_, _| Ok(()))
}

fn apply_edit_plan_atomically_inner<F>(
    plan: Vec<PlannedEdit>,
    mut before_swap: F,
) -> Result<Vec<EditResult>>
where
    F: FnMut(usize, &Path) -> Result<()>,
{
    let staged = stage_edit_plan(plan)?;
    let mut applied = Vec::with_capacity(staged.len());

    for (commit_index, staged_edit) in staged.into_iter().enumerate() {
        if let Err(err) = before_swap(commit_index, &staged_edit.file) {
            match rollback_applied_edits(&applied) {
                Ok(()) => cleanup_edit_backups(&applied),
                Err(rollback_error) => {
                    return Err(err.context(format!("rollback also failed: {rollback_error}")));
                }
            }
            return Err(err);
        }

        let backup_path = edit_backup_path(&staged_edit.file, staged_edit.index);
        if let Err(err) = fs::rename(&staged_edit.file, &backup_path) {
            match rollback_applied_edits(&applied) {
                Ok(()) => cleanup_edit_backups(&applied),
                Err(rollback_error) => {
                    bail!(
                        "moving {} into backup slot failed: {}; rollback also failed: {}",
                        staged_edit.file.display(),
                        err,
                        rollback_error
                    );
                }
            }
            bail!(
                "moving {} into backup slot failed: {}",
                staged_edit.file.display(),
                err
            );
        }
        match staged_edit.staged_file.persist(&staged_edit.file) {
            Ok(_) => applied.push(AppliedEdit {
                index: staged_edit.index,
                file: staged_edit.file,
                replacements: staged_edit.replacements,
                backup_path,
            }),
            Err(err) => {
                let persist_error = err.error;
                drop(err.file);
                let restore_error = fs::rename(&backup_path, &staged_edit.file).err();
                let rollback_error = rollback_applied_edits(&applied).err();
                if rollback_error.is_none() {
                    cleanup_edit_backups(&applied);
                }
                let mut message = format!(
                    "committing {} failed: {}",
                    staged_edit.file.display(),
                    persist_error
                );
                if let Some(restore_error) = restore_error {
                    message.push_str(&format!(
                        "; restoring original {} failed: {}",
                        staged_edit.file.display(),
                        restore_error
                    ));
                }
                if let Some(rollback_error) = rollback_error {
                    message.push_str(&format!("; rollback also failed: {rollback_error}"));
                }
                bail!(message);
            }
        }
    }

    applied.sort_by_key(|entry| entry.index);
    let results = ok_results_from_applied(&applied);
    cleanup_edit_backups(&applied);
    Ok(results)
}

fn cmd_edit(
    dry_run: bool,
    file: Option<PathBuf>,
    compact: bool,
    pretty: bool,
    terse: bool,
    schema: bool,
) -> Result<()> {
    let input = match file {
        Some(path) => fs::read_to_string(&path)
            .with_context(|| format!("reading edit file: {}", path.display()))?,
        None => {
            let mut buf = String::new();
            std::io::stdin()
                .read_to_string(&mut buf)
                .context("reading edits from stdin")?;
            buf
        }
    };
    let batch: EditBatch = serde_json::from_str(&input).context("parsing edit JSON")?;

    if batch.edits.is_empty() {
        println!("No edits provided.");
        return Ok(());
    }

    let plan = build_edit_plan(&batch)?;
    let results: Vec<EditResult> = if dry_run {
        plan.iter()
            .map(|entry| EditResult {
                file: entry.file.clone(),
                status: EditStatus::Skipped,
                error: Some("dry run".into()),
                replacements: Some(entry.replacements),
            })
            .collect()
    } else {
        apply_edit_plan_atomically(plan)?
    };

    // Summary output
    let ok_count = results
        .iter()
        .filter(|r| matches!(r.status, EditStatus::Ok))
        .count();
    let skip_count = results
        .iter()
        .filter(|r| matches!(r.status, EditStatus::Skipped))
        .count();
    let err_count = 0usize;

    if compact {
        println!(
            "applied:{} skipped:{} errors:{}",
            ok_count, skip_count, err_count
        );
    } else {
        println!(
            "{}",
            to_json_schema(
                &serde_json::json!({
                    "applied": ok_count,
                    "skipped": skip_count,
                    "errors": err_count,
                    "results": results,
                }),
                pretty,
                terse,
                schema
            )?
        );
    }

    if err_count > 0 {
        bail!("{} edit(s) failed", err_count);
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn cmd_index(
    path: &std::path::Path,
    rebuild: bool,
    check: bool,
    exit_code: bool,
    prune: bool,
    quiet: bool,
    workspace: bool,
    submodule: Option<&str>,
    json_output: bool,
    compact: bool,
    pretty: bool,
    terse: bool,
    absolute: bool,
    schema: bool,
) -> Result<()> {
    let quiet = quiet || exit_code;
    let root = lint::resolve_project_root_or_canonical_path(path)?;

    if workspace || submodule.is_some() {
        let cfg = config::Config::load(&root)?;
        let targets: Vec<(String, PathBuf, Option<config::WorkspaceScope>)> =
            if let Some(name) = submodule {
                let scope = config::Config::resolve_submodule(&root, name)?;
                vec![(scope.id.clone(), scope.source_root.clone(), Some(scope))]
            } else {
                config::Config::submodule_dirs(&root)?
                    .into_iter()
                    .map(|scope| (scope.id.clone(), scope.source_root.clone(), Some(scope)))
                    .collect()
            };

        if targets.is_empty() {
            bail!("no submodules found in {}", root.display());
        }

        let mut any_stale = false;
        for (name, sub_path, scope) in &targets {
            if !sub_path.exists() {
                eprintln!("  skip {} (not found: {})", name, sub_path.display());
                continue;
            }
            let db_path = cfg.db_path_for(&root, name);
            let mut summary = if rebuild {
                run_index_update(
                    &db_path,
                    sub_path,
                    format!("rebuilding submodule `{}` index", name),
                    &root,
                    Some(name.as_str()),
                    true,
                    false,
                )?
            } else if check {
                index::IndexDb::inspect_read_only(&db_path, sub_path, prune)?.summary
            } else if prune {
                run_index_update(
                    &db_path,
                    sub_path,
                    format!("pruning submodule `{}` index", name),
                    &root,
                    Some(name.as_str()),
                    false,
                    true,
                )?
            } else {
                run_index_update(
                    &db_path,
                    sub_path,
                    format!("indexing submodule `{}`", name),
                    &root,
                    Some(name.as_str()),
                    false,
                    false,
                )?
            };
            if !absolute {
                relativize_index_summary(&mut summary, sub_path);
            }
            if summary.has_changes() {
                any_stale = true;
            }
            let tier = scope
                .as_ref()
                .map(|scope| cfg.tier_for_scope(scope))
                .unwrap_or_else(|| cfg.tier_for(name));
            if json_output {
                let entry = if quiet {
                    serde_json::json!({
                        "submodule": name,
                        "tier": format!("{:?}", tier).to_lowercase(),
                        "total_tracked": summary.total_tracked,
                        "new": summary.new,
                        "modified": summary.modified,
                        "deleted": summary.deleted,
                        "unchanged": summary.unchanged,
                    })
                } else {
                    serde_json::json!({
                        "submodule": name,
                        "tier": format!("{:?}", tier).to_lowercase(),
                        "summary": summary,
                    })
                };
                println!(
                    "{}",
                    if quiet {
                        serde_json::to_string(&entry)?
                    } else {
                        to_json_schema(&entry, pretty, terse, schema)?
                    }
                );
            } else if compact {
                let mode = if rebuild {
                    "rebuild"
                } else if check {
                    "check"
                } else if prune {
                    "prune-safe"
                } else {
                    "incremental"
                };
                print!(
                    "[{}] {} {:?} tracked:{} new:{} mod:{} del:{} unch:{}",
                    name,
                    mode,
                    tier,
                    summary.total_tracked,
                    summary.new,
                    summary.modified,
                    summary.deleted,
                    summary.unchanged
                );
                if let Some(ref ps) = summary.prune_stats {
                    print!(
                        " pruned:{} walked:{} skipped:{}",
                        ps.dirs_pruned, ps.dirs_walked, ps.files_pruned
                    );
                }
                println!();
            } else {
                let mode = if rebuild {
                    "rebuild"
                } else if check {
                    "check"
                } else if prune {
                    "prune-safe"
                } else {
                    "incremental"
                };
                print!(
                    "[{}] ({}, {:?}) {} files tracked — new:{} mod:{} del:{} unch:{}",
                    name,
                    mode,
                    tier,
                    summary.total_tracked,
                    summary.new,
                    summary.modified,
                    summary.deleted,
                    summary.unchanged
                );
                if let Some(ref ps) = summary.prune_stats {
                    print!(
                        " | pruned:{} dirs ({}d walked, {} files skipped)",
                        ps.dirs_pruned, ps.dirs_walked, ps.files_pruned
                    );
                }
                println!();
            }
        }
        if exit_code && check && any_stale {
            std::process::exit(1);
        }
        return Ok(());
    }

    let db_path = root.join(".tsift/index.db");
    let summary = if rebuild {
        run_index_update(
            &db_path,
            &root,
            "rebuilding index".to_string(),
            &root,
            None,
            true,
            false,
        )?
    } else if check {
        index::IndexDb::inspect_read_only(&db_path, &root, prune)?.summary
    } else if prune {
        run_index_update(
            &db_path,
            &root,
            "scanning index (--prune safety mode)".to_string(),
            &root,
            None,
            false,
            true,
        )?
    } else {
        run_index_update(
            &db_path,
            &root,
            "indexing index".to_string(),
            &root,
            None,
            false,
            false,
        )?
    };

    let mut summary = summary;
    if !absolute {
        relativize_index_summary(&mut summary, &root);
    }

    if json_output {
        if quiet {
            let compact = serde_json::json!({
                "total_tracked": summary.total_tracked,
                "new": summary.new,
                "modified": summary.modified,
                "deleted": summary.deleted,
                "unchanged": summary.unchanged,
                "prune_stats": summary.prune_stats,
            });
            println!("{}", serde_json::to_string(&compact)?);
        } else {
            println!("{}", to_json_schema(&summary, pretty, terse, schema)?);
        }
    } else if compact {
        let mode = if rebuild {
            "rebuild"
        } else if check {
            "check"
        } else if prune {
            "prune-safe"
        } else {
            "incremental"
        };
        print!(
            "index {} tracked:{} new:{} mod:{} del:{} unch:{}",
            mode,
            summary.total_tracked,
            summary.new,
            summary.modified,
            summary.deleted,
            summary.unchanged
        );
        if let Some(ref ps) = summary.prune_stats {
            print!(
                " pruned:{} walked:{} skipped:{}",
                ps.dirs_pruned, ps.dirs_walked, ps.files_pruned
            );
        }
        println!();
    } else {
        let mode = if rebuild {
            "rebuild"
        } else if check {
            "check"
        } else if prune {
            "prune-safe"
        } else {
            "incremental"
        };
        println!("Index ({}): {} files tracked", mode, summary.total_tracked);
        print!(
            "  new: {}  modified: {}  deleted: {}  unchanged: {}",
            summary.new, summary.modified, summary.deleted, summary.unchanged
        );
        if let Some(ref ps) = summary.prune_stats {
            print!(
                " | pruned: {} dirs ({} walked, {} files skipped)",
                ps.dirs_pruned, ps.dirs_walked, ps.files_pruned
            );
        }
        println!();
        if !quiet && !summary.changes.is_empty() {
            println!();
            for change in &summary.changes {
                let marker = match change.kind {
                    index::ChangeKind::New => "+",
                    index::ChangeKind::Modified => "~",
                    index::ChangeKind::Deleted => "-",
                };
                let lang = change.language.as_deref().unwrap_or("");
                println!("  {} {} [{}]", marker, change.path.display(), lang);
            }
        }
    }
    if exit_code && check && summary.has_changes() {
        std::process::exit(1);
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn cmd_graph(
    symbol: &str,
    path: &std::path::Path,
    callers: bool,
    callees: bool,
    scope: Option<&str>,
    limit: usize,
    json_output: bool,
    compact: bool,
    pretty: bool,
    terse: bool,
    absolute: bool,
    tabular: bool,
    schema: bool,
    tagpath_opts: TagpathSearchOpts,
) -> Result<()> {
    let root = lint::resolve_project_root_or_canonical_path(path)?;
    let db = open_index_db(path, scope)?;

    let show_both = !callers && !callees;
    // Shared mutable state for diagnostic aggregation across the per-side
    // annotation passes. Cell-style indirection avoids a closure that
    // mutably borrows these locals (the immutable borrow used by the JSON
    // emit sites would otherwise conflict).
    let tagpath_state = std::cell::RefCell::new((
        false,                  // emitted to stderr yet?
        false,                  // any diag.stale=true?
        Option::<String>::None, // first stale reason
    ));
    let maybe_emit_stale_diagnostic = |diag: &TagpathAnnotationDiagnostic| {
        let mut state = tagpath_state.borrow_mut();
        if diag.stale {
            state.1 = true;
            if state.2.is_none() {
                state.2 = diag.reason.clone();
            }
        }
        if !state.0 && diag.stale && !tagpath_opts.no_tagpath {
            eprintln!(
                "tagpath_index_stale: true (reason={}); falling back to live extraction",
                diag.reason.as_deref().unwrap_or("unknown"),
            );
            state.0 = true;
        }
    };

    if callers || show_both {
        let mut edges = db.callers_of(symbol)?;
        let diag = annotate_stored_edges_with_tagpath(
            &mut edges,
            &db,
            &root,
            scope,
            EdgeSide::Caller,
            &tagpath_opts,
        )?;
        maybe_emit_stale_diagnostic(&diag);
        if !absolute {
            relativize_edges(&mut edges, &root);
        }
        let total = edges.len();
        let truncated = limit > 0 && total > limit;
        if truncated {
            edges.truncate(limit);
        }
        if json_output {
            if !show_both {
                let mut out = serde_json::json!({
                    "callers": edges,
                    "total": total,
                    "truncated": truncated,
                });
                {
                    let state = tagpath_state.borrow();
                    inject_tagpath_stale_into_json(
                        &mut out,
                        state.1 && !tagpath_opts.no_tagpath,
                        state.2.as_deref(),
                    );
                }
                println!("{}", to_json_schema(&out, pretty, terse, schema)?);
            }
        } else if tabular {
            println!("direction\tname\tfile\tline");
            for edge in &edges {
                println!(
                    "caller\t{}\t{}\t{}",
                    edge.caller_name, edge.caller_file, edge.call_site_line
                );
            }
            if truncated {
                println!("# (+{} more)", total - limit);
            }
        } else if compact {
            println!("crs[{}]:", total);
            if edges.is_empty() {
                println!("  (none)");
            } else {
                for edge in &edges {
                    println!(
                        "  {} {}:{}",
                        edge.caller_name, edge.caller_file, edge.call_site_line
                    );
                }
                if truncated {
                    println!("  (+{} more)", total - limit);
                }
            }
        } else {
            println!("Callers of `{}`:", symbol);
            if edges.is_empty() {
                println!("  (none)");
            } else {
                for edge in &edges {
                    println!(
                        "  {} ({}:{})",
                        edge.caller_name, edge.caller_file, edge.call_site_line
                    );
                }
                if truncated {
                    println!("  (+{} more, use --limit 0 to show all)", total - limit);
                }
            }
        }
        if show_both && !json_output && !compact && !tabular {
            println!();
        }
    }

    if callees || show_both {
        let mut edges = db.callees_of(symbol)?;
        let diag = annotate_stored_edges_with_tagpath(
            &mut edges,
            &db,
            &root,
            scope,
            EdgeSide::Callee,
            &tagpath_opts,
        )?;
        maybe_emit_stale_diagnostic(&diag);
        if !absolute {
            relativize_edges(&mut edges, &root);
        }
        let total = edges.len();
        let truncated = limit > 0 && total > limit;
        if truncated {
            edges.truncate(limit);
        }
        if json_output {
            if !show_both {
                let mut out = serde_json::json!({
                    "callees": edges,
                    "total": total,
                    "truncated": truncated,
                });
                {
                    let state = tagpath_state.borrow();
                    inject_tagpath_stale_into_json(
                        &mut out,
                        state.1 && !tagpath_opts.no_tagpath,
                        state.2.as_deref(),
                    );
                }
                println!("{}", to_json_schema(&out, pretty, terse, schema)?);
            }
        } else if tabular {
            if !show_both {
                println!("direction\tname\tfile\tline");
            }
            for edge in &edges {
                println!(
                    "callee\t{}\t{}\t{}",
                    edge.callee_name, edge.caller_file, edge.call_site_line
                );
            }
            if truncated {
                println!("# (+{} more)", total - limit);
            }
        } else if compact {
            println!("ces[{}]:", total);
            if edges.is_empty() {
                println!("  (none)");
            } else {
                for edge in &edges {
                    println!(
                        "  {} {}:{}",
                        edge.callee_name, edge.caller_file, edge.call_site_line
                    );
                }
                if truncated {
                    println!("  (+{} more)", total - limit);
                }
            }
        } else {
            println!("Callees of `{}`:", symbol);
            if edges.is_empty() {
                println!("  (none)");
            } else {
                for edge in &edges {
                    println!(
                        "  {} ({}:{})",
                        edge.callee_name, edge.caller_file, edge.call_site_line
                    );
                }
                if truncated {
                    println!("  (+{} more, use --limit 0 to show all)", total - limit);
                }
            }
        }
    }

    if show_both && json_output {
        let mut callers_edges = db.callers_of(symbol)?;
        let mut callees_edges = db.callees_of(symbol)?;
        let caller_diag = annotate_stored_edges_with_tagpath(
            &mut callers_edges,
            &db,
            &root,
            scope,
            EdgeSide::Caller,
            &tagpath_opts,
        )?;
        let callee_diag = annotate_stored_edges_with_tagpath(
            &mut callees_edges,
            &db,
            &root,
            scope,
            EdgeSide::Callee,
            &tagpath_opts,
        )?;
        maybe_emit_stale_diagnostic(&caller_diag);
        maybe_emit_stale_diagnostic(&callee_diag);
        if !absolute {
            relativize_edges(&mut callers_edges, &root);
            relativize_edges(&mut callees_edges, &root);
        }
        let callers_total = callers_edges.len();
        let callees_total = callees_edges.len();
        let callers_truncated = limit > 0 && callers_total > limit;
        let callees_truncated = limit > 0 && callees_total > limit;
        if callers_truncated {
            callers_edges.truncate(limit);
        }
        if callees_truncated {
            callees_edges.truncate(limit);
        }
        let mut combined = serde_json::json!({
            "symbol": symbol,
            "callers": callers_edges,
            "callers_total": callers_total,
            "callers_truncated": callers_truncated,
            "callees": callees_edges,
            "callees_total": callees_total,
            "callees_truncated": callees_truncated,
        });
        {
            let state = tagpath_state.borrow();
            inject_tagpath_stale_into_json(
                &mut combined,
                state.1 && !tagpath_opts.no_tagpath,
                state.2.as_deref(),
            );
        }
        println!("{}", to_json_schema(&combined, pretty, terse, schema)?);
    }

    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn cmd_communities(
    path: &std::path::Path,
    scope: Option<&str>,
    min_size: usize,
    limit: usize,
    json_output: bool,
    compact: bool,
    pretty: bool,
    terse: bool,
    tabular: bool,
    schema: bool,
    tagpath_opts: TagpathSearchOpts,
) -> Result<()> {
    let root = lint::resolve_project_root_or_canonical_path(path)?;
    let tagpath_root = query_tagpath_root(&root, path, scope)?;
    let db = open_index_db(path, scope)?;
    let tagpath_part = community_tagpath_cache_part(&tagpath_root, &tagpath_opts)?;
    let CommunityDetectionReport {
        result,
        mut diagnostics,
    } = detect_communities_cached(&db, &root, scope, &tagpath_part)?;
    let mut tagpath_stale = false;
    let mut tagpath_stale_reason: Option<String> = None;

    let filtered: Vec<graph::Community> = result
        .communities
        .iter()
        .filter(|c| c.members.len() >= min_size)
        .cloned()
        .collect();

    let total = filtered.len();
    let truncated = limit > 0 && total > limit;
    let mut display: Vec<graph::Community> = if truncated {
        filtered[..limit].to_vec()
    } else {
        filtered
    };

    let community_annotation =
        annotate_communities_with_tagpath(&mut display, &db, &tagpath_root, &tagpath_opts)?;
    if let Some(diag) = community_annotation.as_ref() {
        if diag.stale && !tagpath_opts.no_tagpath {
            eprintln!(
                "tagpath_index_stale: true (reason={}); falling back to live extraction",
                diag.reason.as_deref().unwrap_or("unknown"),
            );
        }
        if diag.stale {
            tagpath_stale = true;
            tagpath_stale_reason = diag.reason.clone();
        }
    }
    update_community_annotation_diagnostics(
        &mut diagnostics,
        &display,
        community_annotation.as_ref(),
    );

    if json_output {
        let mut out = serde_json::json!({
            "modularity": result.modularity,
            "iterations": result.iterations,
            "node_count": result.node_count,
            "edge_count": result.edge_count,
            "community_count": total,
            "communities": &display,
            "truncated": truncated,
            "community_diagnostics": diagnostics,
        });
        inject_tagpath_stale_into_json(
            &mut out,
            tagpath_stale && !tagpath_opts.no_tagpath,
            tagpath_stale_reason.as_deref(),
        );
        println!("{}", to_json_schema(&out, pretty, terse, schema)?);
    } else if tabular {
        println!("id\tsize\tmembers");
        for (i, community) in display.iter().enumerate() {
            let names: Vec<&str> = community.members.iter().map(|m| m.name.as_str()).collect();
            println!(
                "{}\t{}\t{}",
                i + 1,
                community.members.len(),
                names.join(",")
            );
        }
        if truncated {
            println!("# (+{} more)", total - limit);
        }
    } else if compact {
        println!(
            "comms n:{} e:{} iter:{} q:{:.4} cnt:{}",
            result.node_count, result.edge_count, result.iterations, result.modularity, total
        );
        if display.is_empty() {
            println!("  (none >= {})", min_size);
        } else {
            for (i, community) in display.iter().enumerate() {
                println!(
                    "  {}. {} mbrs {}",
                    i + 1,
                    community.members.len(),
                    compact_members(&community.members, 5)
                );
            }
            if truncated {
                println!("  (+{} more)", total - limit);
            }
        }
    } else {
        println!(
            "Communities ({} nodes, {} edges, {} iterations, Q={:.4})",
            result.node_count, result.edge_count, result.iterations, result.modularity
        );
        if display.is_empty() {
            println!("  (no communities with {} or more members)", min_size);
        } else {
            println!();
            for (i, c) in display.iter().enumerate() {
                println!(
                    "  [{}] {} members (Q={:.4}):",
                    i + 1,
                    c.members.len(),
                    c.modularity_contribution
                );
                for m in &c.members {
                    match &m.tagpath_handle {
                        Some(handle) => println!("    {}  [{}]", m.name, handle),
                        None => println!("    {}", m.name),
                    }
                }
                if i + 1 < display.len() {
                    println!();
                }
            }
            if truncated {
                println!();
                println!(
                    "  (+{} more communities, use --limit 0 to show all)",
                    total - limit
                );
            }
        }
    }
    Ok(())
}

fn resolve_query_db_path(root: &Path, path_hint: &Path, scope: Option<&str>) -> Result<PathBuf> {
    let cfg = config::Config::load(root)?;
    if let Some(scope_name) = scope {
        let scope = config::Config::resolve_submodule(root, scope_name)?;
        return Ok(cfg.db_path_for(root, &scope.id));
    }

    if let Some(scope) = config::Config::infer_submodule_from_path(root, path_hint)? {
        return Ok(cfg.db_path_for(root, &scope.id));
    }

    let db_path = root.join(".tsift/index.db");
    if db_path.exists() {
        return Ok(db_path);
    }

    let scopes = config::Config::submodule_dirs(root)?;
    if scopes.is_empty() {
        return Ok(db_path);
    }

    let available_scopes = scopes
        .iter()
        .map(|scope| scope.id.as_str())
        .collect::<Vec<_>>()
        .join(", ");
    let indexed_scopes = scopes
        .iter()
        .filter(|scope| cfg.db_path_for(root, &scope.id).exists())
        .map(|scope| scope.id.as_str())
        .collect::<Vec<_>>();
    let indexed_label = if indexed_scopes.is_empty() {
        "none".to_string()
    } else {
        indexed_scopes.join(", ")
    };

    bail!(
        "workspace root {} has no shared root index at {}. Read-only graph queries require `--scope <scope>` when the workspace is indexed into `.tsift/indexes/*/index.db`. Available scopes: {}. Indexed scopes: {}.",
        root.display(),
        db_path.display(),
        available_scopes,
        indexed_label
    );
}

fn open_index_db(path: &std::path::Path, scope: Option<&str>) -> Result<index::IndexDb> {
    let root = lint::resolve_project_root_or_canonical_path(path)?;
    let db_path = resolve_query_db_path(&root, path, scope)?;
    if !db_path.exists() {
        bail!(
            "no index found at {}. Run `tsift index` first.",
            db_path.display()
        );
    }
    index::IndexDb::open_read_only_resilient(&db_path)
}

fn query_tagpath_root(
    root: &std::path::Path,
    path_hint: &std::path::Path,
    scope: Option<&str>,
) -> Result<PathBuf> {
    if let Some(scope_name) = scope {
        return Ok(config::Config::resolve_submodule(root, scope_name)?.source_root);
    }
    if let Some(scope) = config::Config::infer_submodule_from_path(root, path_hint)? {
        return Ok(scope.source_root);
    }
    Ok(root.to_path_buf())
}

