fn dependency_dag_backlog_node_for_target(
    store: &impl GraphStore,
    target: &str,
) -> Result<SubstrateGraphNode> {
    let resolved = graph_db_resolve_evidence_target(store, target)?
        .with_context(|| format!("dependency-dag target not found: {target}"))?;
    if resolved.kind == "backlog" {
        return Ok(resolved);
    }
    let Some(ref_id) = resolved.properties.get("ref_id").cloned() else {
        bail!(
            "dependency-dag target {} resolved to {} without a backlog ref_id",
            target,
            resolved.kind
        );
    };
    store
        .nodes_by_kind("backlog")?
        .into_iter()
        .filter(|node| node.properties.get("ref_id") == Some(&ref_id))
        .min_by(|left, right| {
            left.properties
                .get("line")
                .and_then(|value| value.parse::<i64>().ok())
                .cmp(
                    &right
                        .properties
                        .get("line")
                        .and_then(|value| value.parse::<i64>().ok()),
                )
                .then(left.id.cmp(&right.id))
        })
        .with_context(|| format!("dependency-dag backlog node not found for #{ref_id}"))
}

fn dependency_dag_resolve_backlog_nodes(
    root: &Path,
    path: &Path,
    store: &impl GraphStore,
    raw_targets: &[String],
) -> Result<Vec<SubstrateGraphNode>> {
    let mut nodes = Vec::new();
    let mut seen = BTreeSet::new();
    if raw_targets.is_empty() {
        let hinted_path = if path.is_absolute() {
            path.to_path_buf()
        } else {
            root.join(path)
        };
        let hinted_markdown = hinted_path
            .extension()
            .and_then(|ext| ext.to_str())
            .is_some_and(|ext| ext.eq_ignore_ascii_case("md"));
        let hinted_rel = hinted_markdown.then(|| {
            relativize_pathbuf(&hinted_path, root)
                .to_string_lossy()
                .replace('\\', "/")
        });
        for node in store.nodes_by_kind("backlog")? {
            if let Some(expected_path) = &hinted_rel
                && node.properties.get("path") != Some(expected_path)
            {
                continue;
            }
            if seen.insert(node.id.clone()) {
                nodes.push(node);
            }
        }
        if nodes.is_empty() && hinted_rel.is_some() {
            for node in store.nodes_by_kind("backlog")? {
                if seen.insert(node.id.clone()) {
                    nodes.push(node);
                }
            }
        }
    } else {
        for target in raw_targets {
            let normalized = normalize_conflict_target(target).unwrap_or_else(|| target.clone());
            let node = dependency_dag_backlog_node_for_target(store, &normalized)?;
            if seen.insert(node.id.clone()) {
                nodes.push(node);
            }
        }
    }
    if nodes.is_empty() {
        bail!("dependency-dag needs at least one resolvable backlog id");
    }
    nodes.sort_by(|left, right| {
        left.properties
            .get("line")
            .and_then(|value| value.parse::<i64>().ok())
            .cmp(
                &right
                    .properties
                    .get("line")
                    .and_then(|value| value.parse::<i64>().ok()),
            )
            .then(left.id.cmp(&right.id))
    });
    Ok(nodes)
}

fn dependency_dag_node_id(node: &SubstrateGraphNode) -> String {
    node.properties
        .get("ref_id")
        .cloned()
        .unwrap_or_else(|| node.label.trim_start_matches('#').to_string())
}

fn dependency_dag_node_profile(
    root: &Path,
    store: &impl GraphStore,
    node: &SubstrateGraphNode,
    graph_nodes_by_id: &BTreeMap<String, SubstrateGraphNode>,
    graph_edges: &[SubstrateGraphEdge],
    depth: usize,
    limit: usize,
) -> Result<DependencyDagProfile> {
    let id = dependency_dag_node_id(node);
    let mut source_files = BTreeSet::new();
    let mut source_symbols = BTreeSet::new();
    for edge in graph_edges
        .iter()
        .filter(|edge| edge.from_id == node.id && edge.kind == "mentions")
    {
        let Some(target) = graph_nodes_by_id.get(&edge.to_id) else {
            continue;
        };
        match target.kind.as_str() {
            "file" | "route" => {
                if let Some(path) = target.properties.get("path") {
                    source_files.insert(path.clone());
                }
            }
            "symbol" => {
                source_symbols.insert(target.label.clone());
                if let Some(path) = target.properties.get("path") {
                    source_files.insert(path.clone());
                }
            }
            _ => {}
        }
    }

    let max_rows = if limit == 0 { usize::MAX } else { limit };
    for (source, _) in
        graph_db_reachable_nodes_by_kind(store, &node.id, "source_handle", depth, max_rows)?
    {
        if let Some(handle) = conflict_matrix_source_handle(&source) {
            source_files.insert(handle.file);
        }
    }

    let worker_results = graph_nodes_by_id
        .values()
        .filter(|candidate| {
            candidate.kind == "worker_result"
                && candidate.properties.get("ref_id").map(String::as_str) == Some(id.as_str())
        })
        .cloned()
        .collect::<Vec<_>>();
    let worker_feedback = conflict_matrix_worker_feedback(&worker_results);
    let expected_tests = worker_feedback.expected_tests.iter().cloned().collect();
    let config_files = source_files
        .iter()
        .filter(|file| is_planner_config_path(file))
        .cloned()
        .collect();

    let mut semantic_refs = BTreeMap::new();
    for kind in ["semantic_concept", "semantic_entity"] {
        for (semantic, _) in
            graph_db_reachable_nodes_by_kind(store, &node.id, kind, depth, max_rows)?
        {
            let item = conflict_matrix_semantic_ref(root, &semantic);
            semantic_refs
                .entry(format!("{}:{}", item.kind, item.label))
                .or_insert(item);
        }
    }

    Ok(DependencyDagProfile {
        id,
        graph_node_id: node.id.clone(),
        label: node.label.clone(),
        path: node.properties.get("path").cloned(),
        line: node
            .properties
            .get("line")
            .and_then(|value| value.parse::<i64>().ok()),
        detail: node.properties.get("detail").cloned(),
        source_files,
        source_symbols,
        config_files,
        expected_tests,
        semantic_refs,
        worker_feedback,
    })
}

fn dependency_dag_marker_refs(text: &str, markers: &[&str]) -> Vec<String> {
    let lower = text.to_ascii_lowercase();
    let mut refs = Vec::new();
    for marker in markers {
        let mut offset = 0usize;
        while let Some(pos) = lower[offset..].find(marker) {
            let start = offset + pos + marker.len();
            let segment = text[start..]
                .split(['\n', '.'])
                .next()
                .unwrap_or(&text[start..]);
            refs.extend(extract_conflict_target_refs(segment));
            offset = start;
        }
    }
    dedupe_preserve_order(refs)
}

fn dependency_dag_push_edge(
    edges: &mut Vec<DependencyDagEdge>,
    seen: &mut BTreeSet<(String, String, String)>,
    edge: DependencyDagEdge,
) {
    if edge.from == edge.to {
        return;
    }
    if seen.insert((edge.from.clone(), edge.to.clone(), edge.kind.clone())) {
        edges.push(edge);
    }
}

fn dependency_dag_explicit_edges(
    profiles: &[DependencyDagProfile],
    target_ids: &BTreeSet<String>,
    edges: &mut Vec<DependencyDagEdge>,
    seen: &mut BTreeSet<(String, String, String)>,
) {
    for profile in profiles {
        let detail = profile.detail.as_deref().unwrap_or_default();
        for dep in dependency_dag_marker_refs(
            detail,
            &[
                "depends on",
                "depends-on",
                "deps:",
                "after",
                "blocked by",
                "requires",
            ],
        ) {
            if target_ids.contains(&dep) {
                dependency_dag_push_edge(
                    edges,
                    seen,
                    DependencyDagEdge {
                        from: dep.clone(),
                        to: profile.id.clone(),
                        kind: "explicit_depends_on".to_string(),
                        weight: 1000,
                        reasons: vec![format!("{} declares dependency on #{dep}", profile.id)],
                        shared_files: Vec::new(),
                        shared_symbols: Vec::new(),
                        shared_tests: Vec::new(),
                        shared_config_files: Vec::new(),
                        shared_semantic_refs: Vec::new(),
                    },
                );
            }
        }
        for downstream in dependency_dag_marker_refs(detail, &["before", "unblocks"]) {
            if target_ids.contains(&downstream) {
                dependency_dag_push_edge(
                    edges,
                    seen,
                    DependencyDagEdge {
                        from: profile.id.clone(),
                        to: downstream.clone(),
                        kind: "explicit_before".to_string(),
                        weight: 900,
                        reasons: vec![format!(
                            "{} declares it should run before #{downstream}",
                            profile.id
                        )],
                        shared_files: Vec::new(),
                        shared_symbols: Vec::new(),
                        shared_tests: Vec::new(),
                        shared_config_files: Vec::new(),
                        shared_semantic_refs: Vec::new(),
                    },
                );
            }
        }
    }
}

fn dependency_dag_worker_follow_up_edges(
    profiles: &[DependencyDagProfile],
    target_ids: &BTreeSet<String>,
    edges: &mut Vec<DependencyDagEdge>,
    seen: &mut BTreeSet<(String, String, String)>,
) {
    for profile in profiles {
        for follow_up in &profile.worker_feedback.follow_up_ids {
            if target_ids.contains(follow_up) {
                dependency_dag_push_edge(
                    edges,
                    seen,
                    DependencyDagEdge {
                        from: profile.id.clone(),
                        to: follow_up.clone(),
                        kind: "worker_result_follow_up".to_string(),
                        weight: 700,
                        reasons: vec![format!(
                            "worker_result for #{} references follow-up #{}",
                            profile.id, follow_up
                        )],
                        shared_files: Vec::new(),
                        shared_symbols: Vec::new(),
                        shared_tests: Vec::new(),
                        shared_config_files: Vec::new(),
                        shared_semantic_refs: Vec::new(),
                    },
                );
            }
        }
    }
}

fn dependency_dag_overlap_edges(
    profiles: &[DependencyDagProfile],
    edges: &mut Vec<DependencyDagEdge>,
    seen: &mut BTreeSet<(String, String, String)>,
) {
    for left_idx in 0..profiles.len() {
        for right_idx in (left_idx + 1)..profiles.len() {
            let left = &profiles[left_idx];
            let right = &profiles[right_idx];
            let shared_files = sorted_intersection(&left.source_files, &right.source_files);
            let shared_symbols = sorted_intersection(&left.source_symbols, &right.source_symbols);
            let shared_tests = sorted_intersection(&left.expected_tests, &right.expected_tests);
            let shared_config_files = sorted_intersection(&left.config_files, &right.config_files);
            let left_semantic = left.semantic_refs.keys().cloned().collect::<BTreeSet<_>>();
            let right_semantic = right.semantic_refs.keys().cloned().collect::<BTreeSet<_>>();
            let shared_semantic_refs = sorted_intersection(&left_semantic, &right_semantic);
            if shared_files.is_empty()
                && shared_symbols.is_empty()
                && shared_tests.is_empty()
                && shared_config_files.is_empty()
                && shared_semantic_refs.is_empty()
            {
                continue;
            }
            let kind = if shared_files.is_empty()
                && shared_symbols.is_empty()
                && shared_tests.is_empty()
                && shared_config_files.is_empty()
            {
                "semantic_relation"
            } else {
                "shared_resource"
            };
            let mut reasons = Vec::new();
            if !shared_files.is_empty() {
                reasons.push(format!("shared files: {}", shared_files.join(", ")));
            }
            if !shared_symbols.is_empty() {
                reasons.push(format!("shared symbols: {}", shared_symbols.join(", ")));
            }
            if !shared_tests.is_empty() {
                reasons.push(format!("shared tests: {}", shared_tests.join(" && ")));
            }
            if !shared_config_files.is_empty() {
                reasons.push(format!(
                    "shared config files: {}",
                    shared_config_files.join(", ")
                ));
            }
            if !shared_semantic_refs.is_empty() {
                reasons.push(format!(
                    "shared semantic refs: {}",
                    shared_semantic_refs.join(", ")
                ));
            }
            let weight = shared_files.len() * 100
                + shared_config_files.len() * 100
                + shared_symbols.len() * 40
                + shared_tests.len() * 10
                + shared_semantic_refs.len() * 5;
            dependency_dag_push_edge(
                edges,
                seen,
                DependencyDagEdge {
                    from: left.id.clone(),
                    to: right.id.clone(),
                    kind: kind.to_string(),
                    weight,
                    reasons,
                    shared_files,
                    shared_symbols,
                    shared_tests,
                    shared_config_files,
                    shared_semantic_refs,
                },
            );
        }
    }
}

fn dependency_dag_topo_batches(
    targets: &[String],
    edges: &[DependencyDagEdge],
) -> (Vec<DependencyDagTopoBatch>, DependencyDagCycleDiagnostics) {
    let target_set = targets.iter().cloned().collect::<BTreeSet<_>>();
    let order = targets
        .iter()
        .enumerate()
        .map(|(idx, id)| (id.clone(), idx))
        .collect::<BTreeMap<_, _>>();
    let mut indegree = targets
        .iter()
        .map(|id| (id.clone(), 0usize))
        .collect::<BTreeMap<_, _>>();
    let mut outgoing = BTreeMap::<String, Vec<String>>::new();
    let mut seen_pairs = BTreeSet::<(String, String)>::new();
    for edge in edges {
        if !target_set.contains(&edge.from) || !target_set.contains(&edge.to) {
            continue;
        }
        if !seen_pairs.insert((edge.from.clone(), edge.to.clone())) {
            continue;
        }
        *indegree.entry(edge.to.clone()).or_default() += 1;
        outgoing
            .entry(edge.from.clone())
            .or_default()
            .push(edge.to.clone());
    }
    for values in outgoing.values_mut() {
        values.sort_by_key(|id| order.get(id).copied().unwrap_or(usize::MAX));
        values.dedup();
    }

    let mut processed = BTreeSet::new();
    let mut batches = Vec::new();
    loop {
        let mut ready = targets
            .iter()
            .filter(|id| !processed.contains(*id))
            .filter(|id| indegree.get(*id).copied().unwrap_or(0) == 0)
            .cloned()
            .collect::<Vec<_>>();
        ready.sort_by_key(|id| order.get(id).copied().unwrap_or(usize::MAX));
        if ready.is_empty() {
            break;
        }
        for id in &ready {
            processed.insert(id.clone());
            for next in outgoing.get(id).into_iter().flatten() {
                if let Some(value) = indegree.get_mut(next) {
                    *value = value.saturating_sub(1);
                }
            }
        }
        batches.push(DependencyDagTopoBatch {
            batch: batches.len() + 1,
            targets: ready,
        });
    }

    let blocked_nodes = targets
        .iter()
        .filter(|id| !processed.contains(*id))
        .cloned()
        .collect::<Vec<_>>();
    let blocked_set = blocked_nodes.iter().cloned().collect::<BTreeSet<_>>();
    let cycle_edges = edges
        .iter()
        .filter(|edge| blocked_set.contains(&edge.from) && blocked_set.contains(&edge.to))
        .cloned()
        .collect::<Vec<_>>();
    (
        batches,
        DependencyDagCycleDiagnostics {
            has_cycles: !blocked_nodes.is_empty(),
            blocked_nodes,
            cycle_edges,
        },
    )
}

fn dependency_dag_replay_commands(
    path: &Path,
    scope: Option<&str>,
    targets: &[String],
    depth: usize,
    limit: usize,
) -> Vec<String> {
    let target_args = targets
        .iter()
        .map(|target| shell_quote(target))
        .collect::<Vec<_>>()
        .join(" ");
    let mut command = format!(
        "tsift dependency-dag --path {}{} --depth {} --limit {} --json",
        shell_quote(path.to_string_lossy().as_ref()),
        scope
            .map(|scope| format!(" --scope {}", shell_quote(scope)))
            .unwrap_or_default(),
        depth,
        limit
    );
    if !target_args.is_empty() {
        command.push(' ');
        command.push_str(&target_args);
    }
    vec![command]
}

fn build_dependency_dag_report(
    path: &Path,
    scope: Option<&str>,
    raw_targets: &[String],
    depth: usize,
    limit: usize,
) -> Result<DependencyDagReport> {
    let root = lint::resolve_project_root_or_canonical_path(path)?;
    write_traversal_graph_store(&root, path, scope)
        .with_context(|| format!("refreshing graph-db projection for {}", root.display()))?;
    let graph_db = graph_substrate_db_path(&root, scope);
    let store = SqliteGraphStore::open_read_only_resilient(&graph_db)
        .with_context(|| format!("opening graph-db projection: {}", graph_db.display()))?;
    let mut warnings = Vec::new();
    if let Some(recovery) = store.read_only_recovery() {
        warnings.push(graph_db_read_recovery_diagnostic(recovery));
    }
    let freshness = sqlite_graph_freshness(&store, scope.unwrap_or("root"))?;
    if freshness.fail_closed {
        bail!(
            "dependency-dag graph projection failed closed: {}; repair: {}",
            freshness.diagnostics.join("; "),
            graph_db_repair_commands(&root, scope).join("; ")
        );
    }

    let target_nodes = dependency_dag_resolve_backlog_nodes(&root, path, &store, raw_targets)?;
    let graph_nodes = store.all_nodes()?;
    let graph_edges = store.all_edges()?;
    let graph_nodes_by_id = graph_nodes
        .into_iter()
        .map(|node| (node.id.clone(), node))
        .collect::<BTreeMap<_, _>>();
    let profiles = target_nodes
        .iter()
        .map(|node| {
            dependency_dag_node_profile(
                &root,
                &store,
                node,
                &graph_nodes_by_id,
                &graph_edges,
                depth,
                limit,
            )
        })
        .collect::<Result<Vec<_>>>()?;
    let targets = profiles
        .iter()
        .map(|profile| profile.id.clone())
        .collect::<Vec<_>>();
    let target_ids = targets.iter().cloned().collect::<BTreeSet<_>>();

    let mut edges = Vec::new();
    let mut seen_edges = BTreeSet::new();
    dependency_dag_explicit_edges(&profiles, &target_ids, &mut edges, &mut seen_edges);
    dependency_dag_worker_follow_up_edges(&profiles, &target_ids, &mut edges, &mut seen_edges);
    dependency_dag_overlap_edges(&profiles, &mut edges, &mut seen_edges);
    edges.sort_by(|left, right| {
        left.from
            .cmp(&right.from)
            .then(left.to.cmp(&right.to))
            .then(left.kind.cmp(&right.kind))
    });
    let (topo_batches, cycle_diagnostics) = dependency_dag_topo_batches(&targets, &edges);

    let nodes = profiles
        .into_iter()
        .map(|profile| DependencyDagNode {
            id: profile.id,
            graph_node_id: profile.graph_node_id,
            label: profile.label,
            path: profile.path,
            line: profile.line,
            detail: profile.detail,
            source_files: sorted_set(&profile.source_files),
            source_symbols: sorted_set(&profile.source_symbols),
            config_files: sorted_set(&profile.config_files),
            expected_tests: sorted_set(&profile.expected_tests),
            semantic_refs: profile.semantic_refs.into_values().collect(),
            worker_feedback: profile.worker_feedback,
        })
        .collect::<Vec<_>>();
    let projection_hashes = freshness
        .content_hash
        .clone()
        .into_iter()
        .collect::<Vec<_>>();
    let replay_commands = dependency_dag_replay_commands(path, scope, &targets, depth, limit);
    let repair_commands = graph_db_repair_commands(&root, scope);
    let summary = DependencyDagSummary {
        nodes: nodes.len(),
        edges: edges.len(),
        topo_batches: topo_batches.len(),
        has_cycles: cycle_diagnostics.has_cycles,
    };

    Ok(DependencyDagReport {
        contract_version: DEPENDENCY_DAG_CONTRACT_VERSION,
        root: root.to_string_lossy().to_string(),
        scope: scope.map(str::to_string),
        path: path.to_string_lossy().to_string(),
        targets,
        projection_freshness: freshness,
        projection_hashes,
        nodes,
        edges,
        topo_batches,
        cycle_diagnostics,
        summary,
        replay_commands,
        repair_commands,
        warnings,
    })
}

fn print_dependency_dag_human(report: &DependencyDagReport, compact: bool) {
    if compact {
        println!(
            "dependency-dag targets:{} edges:{} batches:{} cycles:{}",
            report.targets.len(),
            report.edges.len(),
            report.topo_batches.len(),
            report.cycle_diagnostics.has_cycles
        );
    } else {
        println!("Dependency DAG");
        println!("  targets: {}", report.targets.join(", "));
        println!("  edges:   {}", report.edges.len());
        println!("  cycles:  {}", report.cycle_diagnostics.has_cycles);
    }
    for batch in &report.topo_batches {
        println!("batch #{}: {}", batch.batch, batch.targets.join(", "));
    }
    for edge in &report.edges {
        println!(
            "edge {} -> {} kind:{} weight:{}",
            edge.from, edge.to, edge.kind, edge.weight
        );
        for reason in &edge.reasons {
            println!("  reason: {reason}");
        }
    }
    if report.cycle_diagnostics.has_cycles {
        println!(
            "cycle blocked nodes: {}",
            report.cycle_diagnostics.blocked_nodes.join(", ")
        );
    }
    for command in &report.replay_commands {
        println!("replay: {command}");
    }
    for command in &report.repair_commands {
        println!("repair: {command}");
    }
    for warning in &report.warnings {
        println!("warning: {warning}");
    }
}

fn cmd_dependency_dag(
    path: &Path,
    scope: Option<&str>,
    raw_targets: &[String],
    depth: usize,
    limit: usize,
    format: OutputFormat,
) -> Result<()> {
    let report = build_dependency_dag_report(path, scope, raw_targets, depth, limit)?;
    if format.json_output {
        print_json_or_envelope(
            &report,
            &format,
            "dependency-dag",
            "topological-planning",
            ToolEnvelopeSummary {
                text: format!(
                    "Dependency DAG for {} target(s): edges={} batches={} cycles={}",
                    report.targets.len(),
                    report.edges.len(),
                    report.topo_batches.len(),
                    report.cycle_diagnostics.has_cycles
                ),
                metrics: vec![
                    envelope_metric("targets", report.targets.len()),
                    envelope_metric("edges", report.edges.len()),
                    envelope_metric("topo_batches", report.topo_batches.len()),
                    envelope_metric("has_cycles", report.cycle_diagnostics.has_cycles),
                ],
            },
            report.cycle_diagnostics.has_cycles,
            report.replay_commands.clone(),
        )
    } else {
        print_dependency_dag_human(&report, format.compact);
        Ok(())
    }
}

fn render_log_digest_from_input(path: &Path, input: &str, format: OutputFormat) -> Result<()> {
    let report = log_digest::compute(path, input)?;
    if format.json_output {
        println!(
            "{}",
            to_json_schema(&report, format.pretty, format.terse, format.schema)?
        );
        return Ok(());
    }

    if format.compact {
        println!(
            "log lines:{} signals:{} repeats:{} files:{} syms:{} stacks:{}",
            report.non_empty_lines,
            report.signal_groups,
            report.repeated_line_groups,
            report.file_ref_groups,
            report.symbol_ref_groups,
            report.stack_groups
        );
        for signal in &report.signals {
            let location = match (&signal.path, signal.line) {
                (Some(path), Some(line)) => format!("{path}:{line}"),
                (Some(path), None) => path.clone(),
                _ => "-".to_string(),
            };
            println!(
                "{} sev:{} count:{} sums:{} msg:{}",
                location,
                signal.severity,
                signal.occurrences,
                log_digest_summary_label(signal.summary_state),
                truncate_for_compact(&signal.message, 80)
            );
        }
        for repeated in &report.repeated_lines {
            println!(
                "repeat count:{} line:{}",
                repeated.occurrences,
                truncate_for_compact(&repeated.line, 80)
            );
        }
        for symbol in &report.symbol_refs {
            println!(
                "sym:{} count:{} sums:{}",
                symbol.symbol,
                symbol.occurrences,
                log_digest_summary_label(symbol.summary_state)
            );
        }
        for warning in &report.warnings {
            println!("warning: {warning}");
        }
        return Ok(());
    }

    println!("Log digest");
    println!("  lines:                    {}", report.total_lines);
    println!("  non-empty lines:          {}", report.non_empty_lines);
    println!("  signal groups:            {}", report.signal_groups);
    println!(
        "  repeated lines:           {}",
        report.repeated_line_groups
    );
    println!(
        "  repeated line instances:  {}",
        report.repeated_line_occurrences
    );
    println!("  file refs:                {}", report.file_ref_groups);
    println!("  symbol refs:              {}", report.symbol_ref_groups);
    println!("  stack groups:             {}", report.stack_groups);

    if !report.signals.is_empty() {
        println!();
        println!("Signals:");
        for signal in &report.signals {
            match (&signal.path, signal.line, signal.column) {
                (Some(path), Some(line), Some(column)) => println!("{path}:{line}:{column}"),
                (Some(path), Some(line), None) => println!("{path}:{line}"),
                (Some(path), None, _) => println!("{path}"),
                (None, _, _) => println!("(no file anchor)"),
            }
            println!("  severity: {}", signal.severity);
            println!("  occurrences: {}", signal.occurrences);
            println!("  message: {}", signal.message);
            println!(
                "  cached summaries: {}",
                log_digest_summary_label(signal.summary_state)
            );
            for summary in &signal.current_summaries {
                println!(
                    "    - {}: {}",
                    summary.symbol,
                    truncate_for_compact(&summary.summary, 160)
                );
            }
        }
    }

    if !report.repeated_lines.is_empty() {
        println!();
        println!("Repeated lines:");
        for repeated in &report.repeated_lines {
            println!(
                "  {}x {}",
                repeated.occurrences,
                truncate_for_compact(&repeated.line, 180)
            );
        }
    }

    if !report.file_refs.is_empty() {
        println!();
        println!("Anchored files:");
        for file_ref in &report.file_refs {
            match (file_ref.line, file_ref.column) {
                (Some(line), Some(column)) => println!("{}:{}:{}", file_ref.path, line, column),
                (Some(line), None) => println!("{}:{}", file_ref.path, line),
                (None, _) => println!("{}", file_ref.path),
            }
            println!("  occurrences: {}", file_ref.occurrences);
            println!(
                "  cached summaries: {}",
                log_digest_summary_label(file_ref.summary_state)
            );
            for summary in &file_ref.current_summaries {
                println!(
                    "    - {}: {}",
                    summary.symbol,
                    truncate_for_compact(&summary.summary, 160)
                );
            }
        }
    }

    if !report.symbol_refs.is_empty() {
        println!();
        println!("Symbol candidates:");
        for symbol in &report.symbol_refs {
            println!("{}", symbol.symbol);
            println!("  occurrences: {}", symbol.occurrences);
            println!(
                "  cached summaries: {}",
                log_digest_summary_label(symbol.summary_state)
            );
            for summary in &symbol.current_summaries {
                println!(
                    "    - {}: {}",
                    summary.symbol,
                    truncate_for_compact(&summary.summary, 160)
                );
            }
        }
    }

    if !report.stack_traces.is_empty() {
        println!();
        println!("Stack groups:");
        for stack in &report.stack_traces {
            println!("  occurrences: {}", stack.occurrences);
            for frame in &stack.frames {
                println!("    - {}", frame);
            }
        }
    }

    for warning in &report.warnings {
        println!("warning: {warning}");
    }
    Ok(())
}

fn metric_digest_trend_label(trend: metric_digest::MetricDigestTrend) -> &'static str {
    match trend {
        metric_digest::MetricDigestTrend::Improved => "improved",
        metric_digest::MetricDigestTrend::Regressed => "regressed",
        metric_digest::MetricDigestTrend::Flat => "flat",
        metric_digest::MetricDigestTrend::Unknown => "changed",
    }
}

fn metric_digest_gate_label(decision: metric_digest::CommunitySearchGateDecision) -> &'static str {
    match decision {
        metric_digest::CommunitySearchGateDecision::Pass => "pass",
        metric_digest::CommunitySearchGateDecision::Block => "block",
    }
}

fn cmd_metric_digest(options: MetricDigestOptions<'_>, format: OutputFormat) -> Result<()> {
    let input = match options.input_path {
        Some(file_path) => fs::read_to_string(file_path)
            .with_context(|| format!("reading metric input: {}", file_path.display()))?,
        None => {
            let mut buf = String::new();
            std::io::stdin()
                .read_to_string(&mut buf)
                .context("reading metric input from stdin")?;
            buf
        }
    };
    if input.trim().is_empty() {
        bail!("no metric input provided; pass --input <file> or pipe JSON/NDJSON on stdin");
    }

    let baseline = match options.baseline_path {
        Some(file_path) => Some(
            fs::read_to_string(file_path)
                .with_context(|| format!("reading metric baseline: {}", file_path.display()))?,
        ),
        None => None,
    };

    let report = metric_digest::compute(
        &input,
        baseline.as_deref(),
        options.metrics,
        options.lower_is_better,
        options.higher_is_better,
        options.history,
        options.top,
    )?;
    if format.json_output {
        println!(
            "{}",
            to_json_schema(&report, format.pretty, format.terse, format.schema)?
        );
        return Ok(());
    }

    if format.compact {
        let previous = report
            .previous_run
            .as_ref()
            .map(|run| run.label.as_str())
            .unwrap_or("-");
        println!(
            "metric runs:{} current:{} previous:{} metrics:{} imp:{} reg:{}",
            report.runs_loaded,
            report.current_run.label,
            previous,
            report.shared_metrics.max(report.current_run.metrics.len()),
            report.top_improvements.len(),
            report.top_regressions.len()
        );
        for delta in &report.metric_deltas {
            println!(
                "{} current:{} prev:{} delta:{} trend:{}",
                delta.metric,
                metric_digest::format_number(delta.current),
                metric_digest::format_number(delta.previous),
                metric_digest::format_number(delta.delta),
                metric_digest_trend_label(delta.trend)
            );
        }
        if let Some(gate) = &report.community_search_gate {
            println!(
                "community-search-gate decision:{} workloads:{} diagnostics:{}",
                metric_digest_gate_label(gate.decision),
                gate.workloads.len(),
                gate.diagnostics.len()
            );
        }
        for warning in &report.warnings {
            println!("warning: {warning}");
        }
        return Ok(());
    }

    println!("Metric digest");
    println!("  runs loaded:    {}", report.runs_loaded);
    println!("  current:        {}", report.current_run.label);
    match report.previous_run.as_ref() {
        Some(previous) => println!("  previous:       {}", previous.label),
        None => println!("  previous:       (none)"),
    }
    println!("  shared metrics: {}", report.shared_metrics);

    if report.metric_deltas.is_empty() {
        println!();
        println!("Current metrics:");
        for (metric, value) in &report.current_run.metrics {
            println!("  {}: {}", metric, metric_digest::format_number(*value));
        }
    } else {
        println!();
        println!("Current vs previous:");
        for delta in &report.metric_deltas {
            let percent = delta
                .percent_delta
                .map(|value| format!(", {value:+.2}%"))
                .unwrap_or_default();
            println!(
                "  {}: {} (prev {}, delta {:+}{}; {})",
                delta.metric,
                metric_digest::format_number(delta.current),
                metric_digest::format_number(delta.previous),
                metric_digest::format_number(delta.delta),
                percent,
                metric_digest_trend_label(delta.trend)
            );
        }
    }

    if !report.top_improvements.is_empty() {
        println!();
        println!("Top improvements:");
        for delta in &report.top_improvements {
            println!(
                "  {}: {} -> {}",
                delta.metric,
                metric_digest::format_number(delta.previous),
                metric_digest::format_number(delta.current)
            );
        }
    }

    if !report.top_regressions.is_empty() {
        println!();
        println!("Top regressions:");
        for delta in &report.top_regressions {
            println!(
                "  {}: {} -> {}",
                delta.metric,
                metric_digest::format_number(delta.previous),
                metric_digest::format_number(delta.current)
            );
        }
    }

    if !report.news_table_markdown.is_empty() {
        println!();
        println!("News-ready table:");
        println!("{}", report.news_table_markdown);
    }

    if let Some(gate) = &report.community_search_gate {
        println!();
        println!("Community search gate:");
        println!("  decision: {}", metric_digest_gate_label(gate.decision));
        println!(
            "  thresholds: duration +{:.1}%, handle coverage {:.1}%, duplicate precision {:.2}, top stability {:.2}",
            gate.max_duration_regression_percent,
            gate.min_handle_coverage_pct,
            gate.min_duplicate_name_precision,
            gate.min_top_community_stability
        );
        for workload in &gate.workloads {
            println!(
                "  {}: {}",
                workload.workload,
                metric_digest_gate_label(workload.status)
            );
            if let Some(duration) = workload.duration_micros {
                let regression = workload
                    .duration_regression_percent
                    .map(|value| format!(" ({value:+.2}%)"))
                    .unwrap_or_default();
                println!(
                    "    duration_micros: {}{}",
                    metric_digest::format_number(duration),
                    regression
                );
            }
            if let Some(coverage) = workload.handle_coverage_pct {
                println!(
                    "    handle_coverage_pct: {}",
                    metric_digest::format_number(coverage)
                );
            }
            if let Some(precision) = workload.duplicate_name_precision {
                println!(
                    "    duplicate_name_precision: {}",
                    metric_digest::format_number(precision)
                );
            }
            if let Some(stability) = workload.top_community_stability {
                println!(
                    "    top_community_stability: {}",
                    metric_digest::format_number(stability)
                );
            }
            for diagnostic in &workload.diagnostics {
                println!("    warning: {diagnostic}");
            }
        }
    }

    for warning in &report.warnings {
        println!("warning: {warning}");
    }
    Ok(())
}

fn cmd_dci_benchmark(fixture_path: &Path, format: OutputFormat) -> Result<()> {
    let input = fs::read_to_string(fixture_path)
        .with_context(|| format!("reading dci-benchmark fixture: {}", fixture_path.display()))?;
    let report = dci_benchmark::compute(&input)?;

    if format.json_output {
        println!(
            "{}",
            to_json_schema(&report, format.pretty, format.terse, format.schema)?
        );
        return Ok(());
    }

    if format.compact {
        println!(
            "dci tasks:{} strategies:{} warnings:{}",
            report.tasks_loaded,
            report.strategies_compared,
            report.warnings.len()
        );
        for summary in &report.strategy_summaries {
            println!(
                "{} rank:{} loc:{}/{} rate:{} calls:{} latency_ms:{} tokens:{}",
                summary.strategy,
                summary.rank,
                summary.localized,
                summary.task_runs,
                dci_benchmark::format_number(summary.localization_rate * 100.0),
                dci_benchmark::format_number(summary.avg_tool_calls),
                dci_benchmark::format_number(summary.avg_latency_ms),
                dci_benchmark::format_number(summary.avg_estimated_tokens)
            );
        }
        for warning in &report.warnings {
            println!("warning: {warning}");
        }
        return Ok(());
    }

    println!("DCI benchmark");
    if let Some(description) = &report.description {
        println!("  description: {}", description);
    }
    println!("  tasks loaded:        {}", report.tasks_loaded);
    println!("  strategies compared: {}", report.strategies_compared);

    println!();
    println!("Strategy summary:");
    for summary in &report.strategy_summaries {
        println!(
            "  #{} {}: localization {}/{} ({:.1}%), avg calls {}, avg latency {}ms, avg tokens {}",
            summary.rank,
            summary.strategy,
            summary.localized,
            summary.task_runs,
            summary.localization_rate * 100.0,
            dci_benchmark::format_number(summary.avg_tool_calls),
            dci_benchmark::format_number(summary.avg_latency_ms),
            dci_benchmark::format_number(summary.avg_estimated_tokens)
        );
    }

    println!();
    println!("Task winners:");
    for row in &report.task_rows {
        let label = row
            .label
            .as_ref()
            .map(|value| format!(" ({value})"))
            .unwrap_or_default();
        println!("  {}{}", row.task_id, label);
        println!("    localized: {}", row.best_localization.join(", "));
        println!(
            "    lowest calls: {}, lowest latency: {}, lowest tokens: {}",
            row.lowest_tool_calls.as_deref().unwrap_or("-"),
            row.lowest_latency.as_deref().unwrap_or("-"),
            row.lowest_token_budget.as_deref().unwrap_or("-")
        );
    }

    for warning in &report.warnings {
        println!("warning: {warning}");
    }
    Ok(())
}

fn cmd_session_digest(
    path: &Path,
    input_path: Option<&Path>,
    source: Option<&str>,
    format: OutputFormat,
) -> Result<()> {
    let input = match input_path {
        Some(file_path) => fs::read_to_string(file_path)
            .with_context(|| format!("reading session transcript: {}", file_path.display()))?,
        None => {
            let mut buf = String::new();
            std::io::stdin()
                .read_to_string(&mut buf)
                .context("reading session transcript from stdin")?;
            buf
        }
    };
    if input.trim().is_empty() {
        bail!("no session input provided; pass --input <file> or pipe transcript on stdin");
    }

    let report = session_digest::compute(path, &input, source)?;
    if format.json_output {
        println!(
            "{}",
            to_json_schema(&report, format.pretty, format.terse, format.schema)?
        );
        return Ok(());
    }

    if format.compact {
        println!(
            "session src:{} prompts:{} cmds:{} files:{} syms:{} fails:{} runtime:{} churn:{} closeout:{}",
            report.source,
            report.prompt_target_count,
            report.command_groups,
            report.file_groups,
            report.symbol_groups,
            report.failure_groups,
            report.runtime_event_groups,
            report.restart_churn_groups,
            report.closeout_groups
        );
        for prompt in &report.prompt_targets {
            println!("prompt: {}", truncate_for_compact(prompt, 100));
        }
        for command in &report.commands {
            println!(
                "cmd count:{} {}",
                command.occurrences,
                truncate_for_compact(&command.command, 100)
            );
        }
        for failure in &report.failures {
            println!(
                "fail {} count:{} {}",
                failure.kind,
                failure.occurrences,
                truncate_for_compact(&failure.message, 100)
            );
        }
        for event in &report.runtime_events {
            println!(
                "runtime count:{} {}",
                event.occurrences,
                truncate_for_compact(&event.event, 100)
            );
        }
        for churn in &report.restart_churn {
            let suffix = churn
                .max_restart_count
                .map(|value| format!(" max_restart:{}", value))
                .unwrap_or_default();
            println!(
                "churn {} count:{}{} {}",
                churn.family,
                churn.occurrences,
                suffix,
                truncate_for_compact(&churn.sample, 100)
            );
        }
        for entry in &report.closeout {
            println!(
                "closeout {} count:{} {}",
                entry.kind,
                entry.occurrences,
                truncate_for_compact(&entry.detail, 100)
            );
        }
        for warning in &report.warnings {
            println!("warning: {warning}");
        }
        return Ok(());
    }

    println!("Session digest ({})", report.source);
    println!("  transcript items: {}", report.transcript_items);
    println!("  prompt targets:   {}", report.prompt_target_count);
    println!("  commands:         {}", report.command_groups);
    println!("  touched files:    {}", report.file_groups);
    println!("  touched symbols:  {}", report.symbol_groups);
    println!("  failures:         {}", report.failure_groups);
    println!("  runtime events:   {}", report.runtime_event_groups);
    println!("  restart churn:    {}", report.restart_churn_groups);
    println!("  closeout:         {}", report.closeout_groups);

    if !report.prompt_targets.is_empty() {
        println!();
        println!("Prompt targets:");
        for prompt in &report.prompt_targets {
            println!("  - {}", prompt);
        }
    }

    if !report.commands.is_empty() {
        println!();
        println!("Commands:");
        for command in &report.commands {
            println!("  - {} ({})", command.command, command.occurrences);
        }
    }

    if !report.touched_files.is_empty() {
        println!();
        println!("Touched files:");
        for path in &report.touched_files {
            println!("  - {} ({})", path.path, path.occurrences);
        }
    }

    if !report.touched_symbols.is_empty() {
        println!();
        println!("Touched symbols:");
        for symbol in &report.touched_symbols {
            println!("  - {} ({})", symbol.symbol, symbol.occurrences);
        }
    }

    if !report.failures.is_empty() {
        println!();
        println!("Failures:");
        for failure in &report.failures {
            println!(
                "  - [{}] {} ({})",
                failure.kind, failure.message, failure.occurrences
            );
        }
    }

    if !report.runtime_events.is_empty() {
        println!();
        println!("Runtime events:");
        for event in &report.runtime_events {
            println!("  - {} ({})", event.event, event.occurrences);
        }
    }

    if !report.restart_churn.is_empty() {
        println!();
        println!("Restart churn:");
        for churn in &report.restart_churn {
            match churn.max_restart_count {
                Some(max_restart_count) => println!(
                    "  - {} ({}) max_restart={} sample: {}",
                    churn.family, churn.occurrences, max_restart_count, churn.sample
                ),
                None => println!(
                    "  - {} ({}) sample: {}",
                    churn.family, churn.occurrences, churn.sample
                ),
            }
        }
    }

    if !report.closeout.is_empty() {
        println!();
        println!("Closeout evidence:");
        for entry in &report.closeout {
            println!(
                "  - [{}] {} ({})",
                entry.kind, entry.detail, entry.occurrences
            );
        }
    }

    for warning in &report.warnings {
        println!("warning: {warning}");
    }
    Ok(())
}

fn cmd_session_cost(
    input_path: Option<&Path>,
    source: Option<&str>,
    format: OutputFormat,
) -> Result<()> {
    let input = match input_path {
        Some(file_path) => fs::read_to_string(file_path)
            .with_context(|| format!("reading session-cost input: {}", file_path.display()))?,
        None => {
            let mut buf = String::new();
            std::io::stdin()
                .read_to_string(&mut buf)
                .context("reading session-cost input from stdin")?;
            buf
        }
    };
    if input.trim().is_empty() {
        bail!(
            "no session-cost input provided; pass --input <file> or pipe transcript/log data on stdin"
        );
    }

    let report = session_cost::compute(&input, source)?;
    if format.json_output {
        println!(
            "{}",
            to_json_schema(&report, format.pretty, format.terse, format.schema)?
        );
        return Ok(());
    }

    if format.compact {
        let cache_ratio = report
            .cached_input_ratio
            .map(|value| format!("{value:.2}%"))
            .unwrap_or_else(|| "-".to_string());
        println!(
            "session-cost src:{} samples:{} prompt:{} cached:{} cache_ratio:{} output:{} total:{} runtime:{} churn:{} loops:{} file_reads:{}",
            report.source,
            report.usage_samples,
            format_compact_count(report.prompt_tokens),
            format_compact_count(report.cached_input_tokens),
            cache_ratio,
            format_compact_count(report.output_tokens),
            format_compact_count(report.total_tokens),
            report.total_runtime_events,
            report.restart_churn_groups,
            report.loop_clusters.len(),
            report.file_read_diagnostics.len()
        );
        for turn in &report.largest_turns {
            println!(
                "turn total:{} prompt:{} cached:{} output:{} label:{}",
                format_compact_count(turn.total_tokens),
                format_compact_count(turn.prompt_tokens),
                format_compact_count(turn.cached_input_tokens),
                format_compact_count(turn.output_tokens),
                truncate_for_compact(&turn.label, 72)
            );
        }
        for event in &report.runtime_events {
            println!("event count:{} {}", event.occurrences, event.event);
        }
        for churn in &report.restart_churn {
            let suffix = churn
                .max_restart_count
                .map(|value| format!(" max_restart:{}", value))
                .unwrap_or_default();
            println!(
                "churn {} count:{}{} {}",
                churn.family,
                churn.occurrences,
                suffix,
                truncate_for_compact(&churn.sample, 100)
            );
        }
        for cluster in &report.loop_clusters {
            println!(
                "loop {} count:{} streak:{} {}",
                cluster.kind,
                cluster.occurrences,
                cluster.max_consecutive,
                truncate_for_compact(&cluster.label, 100)
            );
        }
        for diagnostic in &report.file_read_diagnostics {
            println!(
                "file-read count:{} duplicate_tokens:{} range:{} path:{} follow_up:{}",
                diagnostic.occurrences,
                format_compact_count(diagnostic.duplicate_estimated_tokens),
                diagnostic.range,
                truncate_for_compact(&diagnostic.path, 80),
                diagnostic
                    .follow_up_commands
                    .iter()
                    .map(|command| truncate_for_compact(command, 100))
                    .collect::<Vec<_>>()
                    .join(" || ")
            );
        }
        for guardrail in &report.guardrails {
            println!(
                "guardrail {} {} {}",
                guardrail.severity,
                guardrail.kind,
                truncate_for_compact(&guardrail.message, 100)
            );
        }
        for warning in &report.warnings {
            println!("warning: {warning}");
        }
        return Ok(());
    }

    println!("Session cost digest ({})", report.source);
    println!("  records:                {}", report.record_count);
    println!("  usage samples:          {}", report.usage_samples);
    println!("  prompt tokens:          {}", report.prompt_tokens);
    println!("  cached input tokens:    {}", report.cached_input_tokens);
    println!(
        "  cache creation tokens:  {}",
        report.cache_creation_input_tokens
    );
    println!("  output tokens:          {}", report.output_tokens);
    println!(
        "  reasoning output:       {}",
        report.reasoning_output_tokens
    );
    println!("  total tokens:           {}", report.total_tokens);
    if let Some(ratio) = report.cached_input_ratio {
        println!("  cached input ratio:     {ratio:.2}%");
    }
    println!(
        "  largest turn total:     {}",
        report.largest_turn_total_tokens
    );
    println!("  runtime events:         {}", report.total_runtime_events);
    println!("  runtime groups:         {}", report.runtime_event_groups);
    println!("  restart churn groups:   {}", report.restart_churn_groups);
    println!("  loop clusters:          {}", report.loop_clusters.len());
    println!(
        "  repeated file reads:    {}",
        report.file_read_diagnostics.len()
    );
    if let Some(max_restart_count) = report.max_restart_count {
        println!("  max restart count:      {}", max_restart_count);
    }

    if !report.largest_turns.is_empty() {
        println!();
        println!("Largest turns:");
        for turn in &report.largest_turns {
            println!(
                "  - {}: total {} | prompt {} | cached {} | output {} | reasoning {}",
                turn.label,
                turn.total_tokens,
                turn.prompt_tokens,
                turn.cached_input_tokens,
                turn.output_tokens,
                turn.reasoning_output_tokens
            );
        }
    }

    if !report.runtime_events.is_empty() {
        println!();
        println!("Runtime churn:");
        for event in &report.runtime_events {
            println!("  - {} ({})", event.event, event.occurrences);
        }
    }

    if !report.restart_churn.is_empty() {
        println!();
        println!("Restart churn:");
        for churn in &report.restart_churn {
            match churn.max_restart_count {
                Some(max_restart_count) => println!(
                    "  - {} ({}) max_restart={} sample: {}",
                    churn.family, churn.occurrences, max_restart_count, churn.sample
                ),
                None => println!(
                    "  - {} ({}) sample: {}",
                    churn.family, churn.occurrences, churn.sample
                ),
            }
        }
    }

    if !report.loop_clusters.is_empty() {
        println!();
        println!("Loop clusters:");
        for cluster in &report.loop_clusters {
            println!(
                "  - [{}] {} ({}) max_consecutive={}",
                cluster.kind, cluster.label, cluster.occurrences, cluster.max_consecutive
            );
        }
    }

    if !report.file_read_diagnostics.is_empty() {
        println!();
        println!("Repeated file reads:");
        for diagnostic in &report.file_read_diagnostics {
            println!(
                "  - {} {} ({}) duplicate tokens ~{}",
                diagnostic.path,
                diagnostic.range,
                diagnostic.occurrences,
                diagnostic.duplicate_estimated_tokens
            );
            for command in &diagnostic.follow_up_commands {
                println!("    follow-up: {command}");
            }
        }
    }

    if !report.guardrails.is_empty() {
        println!();
        println!("Guardrails:");
        for guardrail in &report.guardrails {
            println!(
                "  - [{}:{}] {} | guidance: {}",
                guardrail.severity, guardrail.kind, guardrail.message, guardrail.guidance
            );
        }
    }

    for warning in &report.warnings {
        println!("warning: {warning}");
    }
    Ok(())
}

#[allow(dead_code)]
fn cmd_session_review(path: &Path, next_context: bool, format: OutputFormat) -> Result<()> {
    cmd_session_review_with_budget(path, next_context, format, ResponseBudget::default())
}

fn cmd_session_review_with_budget(
    path: &Path,
    next_context: bool,
    format: OutputFormat,
    budget: ResponseBudget,
) -> Result<()> {
    let report = session_review::compute(path)?;
    if budget.is_active() {
        if next_context {
            let budget_report =
                build_session_review_next_context_budget_report(&report, budget, None);
            if format.json_output {
                print_json_or_envelope(
                    &budget_report,
                    &format,
                    "session-review",
                    "next-context-preview",
                    ToolEnvelopeSummary {
                        text: format!("next-context preview for {}", budget_report.target),
                        metrics: vec![
                            envelope_metric("prompt_targets", budget_report.prompt_target_total),
                            envelope_metric("files", budget_report.touched_file_total),
                            envelope_metric("symbols", budget_report.touched_symbol_total),
                            envelope_metric("failures", budget_report.unresolved_failure_total),
                        ],
                    },
                    budget_report.truncated,
                    budget_report.next_digest_commands.clone(),
                )?;
            } else {
                print_session_review_next_context_budget_human(&budget_report);
            }
        } else {
            let budget_report = build_session_review_budget_report(&report, budget);
            if format.json_output {
                let mut follow_up = vec![format!(
                    "tsift session-review {} --next-context --json",
                    shell_quote(&budget_report.target)
                )];
                if let Some(session) = budget_report.sessions.first() {
                    follow_up.push(session.expand.clone());
                }
                print_json_or_envelope(
                    &budget_report,
                    &format,
                    "session-review",
                    "preview",
                    ToolEnvelopeSummary {
                        text: format!("session review preview for {}", budget_report.target),
                        metrics: vec![
                            envelope_metric("sessions", budget_report.sessions_matched),
                            envelope_metric("prompt_targets", budget_report.prompt_targets.len()),
                            envelope_metric("failures", budget_report.failures.len()),
                            envelope_metric("total_tokens", budget_report.total_tokens),
                        ],
                    },
                    budget_report.truncated,
                    follow_up,
                )?;
            } else {
                print_session_review_budget_human(&budget_report);
            }
        }
        return Ok(());
    }
    if next_context {
        if format.json_output {
            print_json_or_envelope(
                &report.next_context,
                &format,
                "session-review",
                "next-context",
                ToolEnvelopeSummary {
                    text: format!("next-context for {}", report.next_context.target),
                    metrics: vec![
                        envelope_metric(
                            "prompt_targets",
                            report.next_context.active_prompt_targets.len(),
                        ),
                        envelope_metric("files", report.next_context.touched_files.len()),
                        envelope_metric("symbols", report.next_context.touched_symbols.len()),
                        envelope_metric("failures", report.next_context.unresolved_failures.len()),
                    ],
                },
                false,
                report.next_context.next_digest_commands.clone(),
            )?;
            return Ok(());
        }

        println!("Next context");
        println!("  target:                 {}", report.next_context.target);
        println!(
            "  prompt targets:         {}",
            report.next_context.active_prompt_targets.len()
        );
        println!(
            "  touched files:          {}",
            report.next_context.touched_files.len()
        );
        println!(
            "  touched symbols:        {}",
            report.next_context.touched_symbols.len()
        );
        println!(
            "  unresolved failures:    {}",
            report.next_context.unresolved_failures.len()
        );
        println!(
            "  last verification:      {}",
            report.next_context.last_verification.status
        );
        println!(
            "  verification detail:    {}",
            report.next_context.last_verification.detail
        );

        if !report.next_context.active_prompt_targets.is_empty() {
            println!();
            println!("Active prompt targets:");
            for prompt in &report.next_context.active_prompt_targets {
                println!("  - {}", prompt);
            }
        }

        if !report.next_context.touched_files.is_empty() {
            println!();
            println!("Touched files:");
            for path in &report.next_context.touched_files {
                println!("  - {}", path);
            }
        }

        if !report.next_context.touched_symbols.is_empty() {
            println!();
            println!("Touched symbols:");
            for symbol in &report.next_context.touched_symbols {
                println!("  - {}", symbol);
            }
        }

        if !report.next_context.unresolved_failures.is_empty() {
            println!();
            println!("Unresolved failures:");
            for failure in &report.next_context.unresolved_failures {
                println!(
                    "  - [{}] {} ({}){}{}",
                    failure.kind,
                    failure.message,
                    failure.occurrences,
                    failure
                        .command
                        .as_ref()
                        .map(|command| format!(" command: {command}"))
                        .unwrap_or_default(),
                    failure
                        .session_path
                        .as_ref()
                        .map(|path| format!(" session: {path}"))
                        .unwrap_or_default()
                );
            }
        }

        println!();
        println!("Next digest commands:");
        for command in &report.next_context.next_digest_commands {
            println!("  - {}", command);
        }
        return Ok(());
    }

    if format.json_output {
        let mut follow_up = vec![format!(
            "tsift session-review {} --next-context --json",
            shell_quote(&report.target)
        )];
        follow_up.extend(report.next_context.next_digest_commands.clone());
        print_json_or_envelope(
            &report,
            &format,
            "session-review",
            "report",
            ToolEnvelopeSummary {
                text: format!("session review for {}", report.target),
                metrics: vec![
                    envelope_metric("sessions", report.sessions_matched),
                    envelope_metric("prompt_targets", report.prompt_target_count),
                    envelope_metric("failures", report.failure_groups),
                    envelope_metric("file_reads", report.file_read_diagnostics.len()),
                    envelope_metric("aggregate_total_tokens", report.total_tokens),
                    envelope_metric(
                        "latest_session_total_tokens",
                        report
                            .latest_session_cost
                            .as_ref()
                            .map_or(0, |cost| cost.total_tokens),
                    ),
                ],
            },
            false,
            follow_up,
        )?;
        return Ok(());
    }

    if format.compact {
        let cache_ratio = report
            .cached_input_ratio
            .map(|value| format!("{value:.2}%"))
            .unwrap_or_else(|| "-".to_string());
        let latest_total = report
            .latest_session_cost
            .as_ref()
            .map(|cost| format_compact_count(cost.total_tokens))
            .unwrap_or_else(|| "-".to_string());
        let latest_largest_turn = report
            .latest_session_cost
            .as_ref()
            .map(|cost| format_compact_count(cost.largest_turn_total_tokens))
            .unwrap_or_else(|| "-".to_string());
        println!(
            "session-review target:{} kind:{} matched:{} claude:{} codex:{} agent_doc:{} aggregate_prompt:{} aggregate_cached:{} aggregate_cache_ratio:{} aggregate_output:{} aggregate_total:{} latest_total:{} latest_largest_turn:{} loops:{} file_reads:{}",
            report.target,
            report.target_kind,
            report.sessions_matched,
            report.claude_sessions,
            report.codex_sessions,
            report.agent_doc_logs,
            format_compact_count(report.prompt_tokens),
            format_compact_count(report.cached_input_tokens),
            cache_ratio,
            format_compact_count(report.output_tokens),
            format_compact_count(report.total_tokens),
            latest_total,
            latest_largest_turn,
            report.loop_clusters.len(),
            report.file_read_diagnostics.len()
        );
        for session in &report.sessions {
            println!(
                "session {} total:{} largest_turn:{} prompts:{} fails:{} matched_by:{} path:{}",
                session.source,
                format_compact_count(session.total_tokens),
                format_compact_count(session.largest_turn_total_tokens),
                session.prompt_target_count,
                session.failure_groups,
                session.matched_by.join(","),
                truncate_for_compact(&session.path, 96)
            );
        }
        for prompt in &report.prompt_targets {
            println!(
                "prompt count:{} {}",
                prompt.occurrences,
                truncate_for_compact(&prompt.text, 100)
            );
        }
        for failure in &report.failures {
            println!(
                "fail {} count:{} {}{}{}",
                failure.kind,
                failure.occurrences,
                truncate_for_compact(&failure.message, 100),
                failure
                    .command
                    .as_ref()
                    .map(|command| format!(" command:{}", truncate_for_compact(command, 80)))
                    .unwrap_or_default(),
                failure
                    .session_path
                    .as_ref()
                    .map(|path| format!(" session:{}", truncate_for_compact(path, 80)))
                    .unwrap_or_default()
            );
        }
        for cluster in &report.loop_clusters {
            println!(
                "loop {} count:{} streak:{} {}",
                cluster.kind,
                cluster.occurrences,
                cluster.max_consecutive,
                truncate_for_compact(&cluster.label, 100)
            );
        }
        for diagnostic in &report.file_read_diagnostics {
            println!(
                "file-read count:{} duplicate_tokens:{} range:{} path:{} follow_up:{}",
                diagnostic.occurrences,
                format_compact_count(diagnostic.duplicate_estimated_tokens),
                diagnostic.range,
                truncate_for_compact(&diagnostic.path, 80),
                diagnostic
                    .follow_up_commands
                    .iter()
                    .map(|command| truncate_for_compact(command, 100))
                    .collect::<Vec<_>>()
                    .join(" || ")
            );
        }
        for guardrail in &report.guardrails {
            println!(
                "guardrail {} {} {}",
                guardrail.severity,
                guardrail.kind,
                truncate_for_compact(&guardrail.message, 100)
            );
        }
        for warning in &report.warnings {
            println!("warning: {warning}");
        }
        return Ok(());
    }

    println!("Session review ({})", report.target_kind);
    println!("  root:                   {}", report.root);
    println!("  target:                 {}", report.target);
    println!("  sessions considered:    {}", report.sessions_considered);
    println!("  sessions matched:       {}", report.sessions_matched);
    println!("  Claude sessions:        {}", report.claude_sessions);
    println!("  Codex sessions:         {}", report.codex_sessions);
    println!("  agent-doc logs:         {}", report.agent_doc_logs);
    println!("  prompt targets:         {}", report.prompt_target_count);
    println!("  commands:               {}", report.command_groups);
    println!("  touched files:          {}", report.file_groups);
    println!("  touched symbols:        {}", report.symbol_groups);
    println!("  failures:               {}", report.failure_groups);
    println!("  runtime events:         {}", report.runtime_event_groups);
    println!("  restart churn:          {}", report.restart_churn_groups);
    println!("  closeout:               {}", report.closeout_groups);
    println!("  loop clusters:          {}", report.loop_clusters.len());
    println!(
        "  repeated file reads:    {}",
        report.file_read_diagnostics.len()
    );
    println!("  aggregate usage samples: {}", report.usage_samples);
    println!("  aggregate prompt tokens: {}", report.prompt_tokens);
    println!("  aggregate cached input: {}", report.cached_input_tokens);
    println!(
        "  aggregate cache create: {}",
        report.cache_creation_input_tokens
    );
    println!("  aggregate output tokens: {}", report.output_tokens);
    println!(
        "  aggregate reasoning out: {}",
        report.reasoning_output_tokens
    );
    println!("  aggregate total tokens: {}", report.total_tokens);
    if let Some(ratio) = report.cached_input_ratio {
        println!("  aggregate cache ratio:  {ratio:.2}%");
    }
    println!(
        "  aggregate largest turn: {}",
        report.largest_turn_total_tokens
    );
    if let Some(latest) = &report.latest_session_cost {
        println!("  latest session tokens:  {}", latest.total_tokens);
        println!(
            "  latest session largest: {}",
            latest.largest_turn_total_tokens
        );
    }

    if !report.sessions.is_empty() {
        println!();
        println!("Matched sessions:");
        for session in &report.sessions {
            println!(
                "  - [{}] {} | total {} | largest turn {} | prompts {} | failures {} | matched by {}",
                session.source,
                session.path,
                session.total_tokens,
                session.largest_turn_total_tokens,
                session.prompt_target_count,
                session.failure_groups,
                session.matched_by.join(", ")
            );
        }
    }

    if !report.prompt_targets.is_empty() {
        println!();
        println!("Prompt targets:");
        for prompt in &report.prompt_targets {
            println!("  - {} ({})", prompt.text, prompt.occurrences);
        }
    }

    if !report.commands.is_empty() {
        println!();
        println!("Commands:");
        for command in &report.commands {
            println!("  - {} ({})", command.command, command.occurrences);
        }
    }

    if !report.failures.is_empty() {
        println!();
        println!("Failures:");
        for failure in &report.failures {
            println!(
                "  - [{}] {} ({}){}{}",
                failure.kind,
                failure.message,
                failure.occurrences,
                failure
                    .command
                    .as_ref()
                    .map(|command| format!(" command: {command}"))
                    .unwrap_or_default(),
                failure
                    .session_path
                    .as_ref()
                    .map(|path| format!(" session: {path}"))
                    .unwrap_or_default()
            );
        }
    }

    if !report.restart_churn.is_empty() {
        println!();
        println!("Restart churn:");
        for churn in &report.restart_churn {
            match churn.max_restart_count {
                Some(max_restart_count) => println!(
                    "  - {} ({}) max_restart={} sample: {}",
                    churn.family, churn.occurrences, max_restart_count, churn.sample
                ),
                None => println!(
                    "  - {} ({}) sample: {}",
                    churn.family, churn.occurrences, churn.sample
                ),
            }
        }
    }

    if !report.closeout.is_empty() {
        println!();
        println!("Closeout evidence:");
        for entry in &report.closeout {
            println!(
                "  - [{}] {} ({})",
                entry.kind, entry.detail, entry.occurrences
            );
        }
    }

    if !report.loop_clusters.is_empty() {
        println!();
        println!("Loop clusters:");
        for cluster in &report.loop_clusters {
            println!(
                "  - [{}] {} ({}) max_consecutive={}",
                cluster.kind, cluster.label, cluster.occurrences, cluster.max_consecutive
            );
        }
    }

    if !report.file_read_diagnostics.is_empty() {
        println!();
        println!("Repeated file reads:");
        for diagnostic in &report.file_read_diagnostics {
            println!(
                "  - {} {} ({}) duplicate tokens ~{}",
                diagnostic.path,
                diagnostic.range,
                diagnostic.occurrences,
                diagnostic.duplicate_estimated_tokens
            );
            for command in &diagnostic.follow_up_commands {
                println!("    follow-up: {command}");
            }
        }
    }

    if !report.largest_turns.is_empty() {
        println!();
        println!("Largest turns:");
        for turn in &report.largest_turns {
            println!(
                "  - [{}] {}: total {} | prompt {} | cached {} | output {} | reasoning {}",
                turn.source,
                turn.label,
                turn.total_tokens,
                turn.prompt_tokens,
                turn.cached_input_tokens,
                turn.output_tokens,
                turn.reasoning_output_tokens
            );
        }
    }

    if !report.guardrails.is_empty() {
        println!();
        println!("Guardrails:");
        for guardrail in &report.guardrails {
            println!(
                "  - [{}:{}] {} | guidance: {}",
                guardrail.severity, guardrail.kind, guardrail.message, guardrail.guidance
            );
        }
    }

    for warning in &report.warnings {
        println!("warning: {warning}");
    }
    Ok(())
}

